// ===========================================
// Page Object for a Login Page
// ===========================================
public class LoginPage {
    private WebDriver driver;
    // Locators are stored in one place
    private By usernameField = By.id("username");
    private By passwordField = By.id("password");
    private By loginButton = By.cssSelector("button[type='submit']");
    private By errorMessage = By.className("error");

    public LoginPage(WebDriver driver) {
        this.driver = driver;
    }

    // Methods encapsulate actions on the page
    public LoginPage enterUsername(String username) {
        driver.findElement(usernameField).sendKeys(username);
        return this; // Fluent interface
    }

    public LoginPage enterPassword(String password) {
        driver.findElement(passwordField).sendKeys(password);
        return this;
    }

    public HomePage clickLoginButton() {
        driver.findElement(loginButton).click();
        return new HomePage(driver); // Navigates to the next page
    }

    public String getErrorMessage() {
        return driver.findElement(errorMessage).getText();
    }

    // Combined action for a common workflow
    public HomePage loginAs(String username, String password) {
        return this.enterUsername(username)
                   .enterPassword(password)
                   .clickLoginButton();
    }
}

// ===========================================
// Test Using the Page Object
// ===========================================
@Test
public void testValidLogin() {
    LoginPage loginPage = new LoginPage(driver);
    // The test is clean and readable. If the login button ID changes,
    // we only update LoginPage.java, not this test.
    HomePage homePage = loginPage.loginAs("standard_user", "secret_sauce");
    assertTrue(homePage.isDashboardDisplayed());
}

