import org.junit.jupiter.api.*;

class JunitLifecycleTest {

    @BeforeAll
    static void initAll() {
        System.out.println("JUnit: @BeforeAll - Runs once before any test");
    }

    @BeforeEach
    void init() {
        System.out.println("JUnit: @BeforeEach - Runs before each test");
    }

    @Test
    void testOne() {
        System.out.println("JUnit: Test One");
        Assertions.assertTrue(true);
    }

    @Test
    void testTwo() {
        System.out.println("JUnit: Test Two");
        Assertions.assertEquals(2, 1 + 1);
    }

    @AfterEach
    void tearDown() {
        System.out.println("JUnit: @AfterEach - Runs after each test");
    }

    @AfterAll
    static void tearDownAll() {
        System.out.println("JUnit: @AfterAll - Runs once after all tests");
    }
}

