import org.testng.annotations.*;

public class SuiteLevelTest {

    @BeforeSuite
    public void beforeSuite() {
        System.out.println("@BeforeSuite: Runs once before the entire suite (e.g., start Grid Hub)");
    }

    @AfterSuite
    public void afterSuite() {
        System.out.println("@AfterSuite: Runs once after the entire suite (e.g., stop Grid Hub)");
    }

    @BeforeTest
    public void beforeTest() {
        System.out.println("@BeforeTest: Runs before each <test> tag in testng.xml (e.g., initialize for a specific browser)");
    }

    @AfterTest
    public void afterTest() {
        System.out.println("@AfterTest: Runs after each <test> tag");
    }

    @BeforeGroups(groups = "smoke")
    public void beforeSmokeGroup() {
        System.out.println("@BeforeGroups: Runs before the first test in 'smoke' group");
    }

    @AfterGroups(groups = "smoke")
    public void afterSmokeGroup() {
        System.out.println("@AfterGroups: Runs after the last test in 'smoke' group");
    }

    @Test(groups = "smoke")
    public void smokeTest1() {
        System.out.println("Smoke Test 1");
    }

    @Test(groups = "smoke")
    public void smokeTest2() {
        System.out.println("Smoke Test 2");
    }

    @Test(groups = "regression")
    public void regressionTest() {
        System.out.println("Regression Test");
    }
}

