import org.testng.annotations.Test;
import org.testng.asserts.SoftAssert;

public class SoftAssertTest {

    @Test
    public void testMultipleValidations() {
        SoftAssert softAssert = new SoftAssert();

        System.out.println("Starting test with soft assertions...");

        // First validation
        int actualSum = 2 + 2;
        softAssert.assertEquals(actualSum, 5, "Sum should be 5"); // This will fail

        // Second validation
        String actualTitle = "Welcome to Dashboard";
        softAssert.assertTrue(actualTitle.startsWith("Welcome"), "Title should start with 'Welcome'"); // This passes

        // Third validation
        boolean isButtonPresent = false;
        softAssert.assertTrue(isButtonPresent, "Submit button should be present"); // This will fail

        System.out.println("All validations executed. Now collecting results...");

        // This line will throw an assertion error containing all collected failures
        softAssert.assertAll();
    }
}

