// JUnit 5 - Using assertThrows
// ===========================================
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class ExceptionTestJUnit {

    @Test
    void testDivideByZeroThrowsException() {
        Calculator calculator = new Calculator();

        // assertThrows returns the exception, allowing further assertions
        ArithmeticException exception = assertThrows(
                ArithmeticException.class,
                () -> calculator.divide(10, 0)
        );

        assertEquals("/ by zero", exception.getMessage());
    }

    @Test
    void testMultipleExceptionTypes() {
        // Use assertThrowsExactly if you want the exact class, not a subclass
        assertThrowsExactly(IllegalArgumentException.class,
                () -> new User(null, -5));
    }
}


