// TestNG - Using expectedExceptions attribute
// ===========================================
import org.testng.annotations.Test;

public class ExceptionTestNG {

    @Test(expectedExceptions = ArithmeticException.class,
          expectedExceptionsMessageRegExp = "/ by zero") // Optional message regex
    public void testDivideByZeroThrowsException() {
        Calculator calculator = new Calculator();
        calculator.divide(10, 0);
    }

    @Test
    public void testExceptionWithMoreChecks() {
        try {
            new User(null, -5);
            org.testng.Assert.fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            org.testng.Assert.assertEquals(e.getMessage(), "Invalid user data");
        }
    }
}

