    <test name="Full Regression">
        <groups>
            <run>
                <include name="regression" />
            </run>
        </groups>
        <classes>
            <class name="com.example.tests.GroupTest" />
        </classes>
    </test>

    <!-- Meta-group: Run both smoke and regression -->
    <test name="All Tests">
        <groups>
            <define name="all">
                <include name="smoke"/>
                <include name="regression"/>
            </define>
            <run>
                <include name="all"/>
            </run>
        </groups>
    </test>
</suite>

