import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Assertions;
import java.time.Duration;
import java.util.Arrays;
import java.util.List;

public class HardAssertionsCompleteTest {

    @Test
    void testAllAssertions() {
        // Basic equality
        Assertions.assertEquals(5, 2 + 3, "2+3 should equal 5");
        Assertions.assertNotEquals(10, 2 + 3, "2+3 should not equal 10");

        // Boolean conditions
        Assertions.assertTrue("Hello World".startsWith("Hello"));
        Assertions.assertFalse("Hello World".endsWith("Goodbye"));

        // Null checks
        String nullString = null;
        String nonNullString = "test";
        Assertions.assertNull(nullString);
        Assertions.assertNotNull(nonNullString);

        // Object references
        String s1 = "hello";
        String s2 = "hello";
        String s3 = new String("hello");
        Assertions.assertSame(s1, s2); // Same reference (string interning)
        Assertions.assertNotSame(s1, s3); // Different objects

        // Array equality
        int[] expected = {1, 2, 3, 4, 5};
        int[] actual = {1, 2, 3, 4, 5};
        Assertions.assertArrayEquals(expected, actual);

        // Iterable equality
        List<String> expectedList = Arrays.asList("apple", "banana", "cherry");
        List<String> actualList = Arrays.asList("apple", "banana", "cherry");
        Assertions.assertIterableEquals(expectedList, actualList);

        // Timeout assertions
        Assertions.assertTimeout(Duration.ofMillis(100), () -> {
            Thread.sleep(50); // This passes (50ms < 100ms)
        });

        // Exception assertions
        Assertions.assertThrows(ArithmeticException.class, () -> {
            int result = 10 / 0;
        });

        // Multiple assertions in one test (all run, but first failure stops the test)
        // This is where soft assertions would be better
    }

    @Test
    void testFailExample() {
        // Conditional fail based on environment
        String environment = System.getProperty("env", "dev");
        if ("prod".equals(environment)) {
            // This test shouldn't run in production
            Assertions.fail("This test should not be executed in production environment");
        }
    }
}

