            .doesNotContain("Goodbye");
    }

    @Test
    void testCollectionAssertions() {
        List<String> fruits = List.of("apple", "banana", "cherry");

        assertThat(fruits)
            .hasSize(3)
            .contains("banana")
            .containsExactly("apple", "banana", "cherry")
            .doesNotContain("grape")
            .allSatisfy(fruit -> {
                assertThat(fruit).isNotBlank();
                assertThat(fruit).hasSizeGreaterThan(3);
            });
    }

    @Test
    void testNumberAssertions() {
        int actual = 42;

        assertThat(actual)
            .isGreaterThan(40)
            .isLessThan(50)
            .isBetween(40, 45)
            .isNotZero();
    }

    @Test
    void testDateAssertions() {
        LocalDate today = LocalDate.now();
        LocalDate tomorrow = today.plusDays(1);

        assertThat(tomorrow)
            .isAfter(today)
            .isNotEqualTo(today)
            .isToday() // This would fail
            .isEqualTo(today.plusDays(1));
    }

    @Test
    void testOptionalAssertions() {
        Optional<String> optional = Optional.of("value");

        assertThat(optional)
            .isPresent()
            .hasValue("value")
            .contains("value");

        Optional<String> empty = Optional.empty();
        assertThat(empty).isEmpty();
    }

    @Test
    void testExceptionAssertions() {
        // AssertJ has excellent exception assertions
        assertThatThrownBy(() -> {
            int result = 10 / 0;
        })
            .isInstanceOf(ArithmeticException.class)
            .hasMessage("/ by zero")
            .hasNoCause();

        // Alternative: assertThatCode for code that shouldn't throw
        assertThatCode(() -> {
            int result = 10 / 2;
        }).doesNotThrowAnyException();
    }

    @Test
    void testExtractingFields() {
        List<User> users = List.of(
            new User("Alice", 30),
            new User("Bob", 25),
            new User("Charlie", 35)
        );

        // Extract a field from each object and assert
        assertThat(users)
            .extracting(User::getName)
            .contains("Alice", "Bob", "Charlie");

        // Extract multiple fields
        assertThat(users)
            .extracting(User::getName, User::getAge)
            .containsExactly(
                tuple("Alice", 30),
                tuple("Bob", 25),
                tuple("Charlie", 35)
            );
    }

    // Helper class
    static class User {
        private String name;
        private int age;
        // constructor, getters...
    }
}

public class AssertionAntiPatterns {

    // ANTI-PATTERN 1: Asserting multiple things without soft assertions
    @Test
    void badTest() {
        // First failure stops the test - you won't see others
        assertEquals("John", user.getName());
        assertEquals(30, user.getAge());
        assertTrue(user.isActive());
    }

    // GOOD: Use soft assertions for multiple validations
    @Test
    void goodTest() {
        SoftAssert softly = new SoftAssert();
        softly.assertEquals(user.getName(), "John");
        softly.assertEquals(user.getAge(), 30);
        softly.assertTrue(user.isActive());
        softly.assertAll();
    }

    // ANTI-PATTERN 2: No assertion message
    @Test
    void badTest2() {
        assertEquals(5, calculateSomething());
        // When this fails, you see: expected 5 but was 3
        // But you have no idea what calculateSomething() is supposed to do
    }

    // GOOD: Descriptive message
    @Test
    void goodTest2() {
        assertEquals(5, calculateSomething(),
            "Total price after discount should be $5");
    }

    // ANTI-PATTERN 3: Asserting too many implementation details
    @Test
    void badTest3() {
        // This test breaks if internal implementation changes, even if behavior is correct
        Map<String, Object> internalState = service.getInternalState();
        assertEquals(3, internalState.size());
        assertEquals("value", internalState.get("key"));
    }

    // GOOD: Assert the public behavior, not internal state
    @Test
    void goodTest3() {
        String result = service.performAction("input");
        assertEquals("expected output", result);
    }

    // ANTI-PATTERN 4: Using assertTrue for everything
    @Test
    void badTest4() {
        assertTrue("Hello World".startsWith("Hello")); // Works but message is poor
        assertTrue(5 == 2 + 3); // Avoid this!
    }

    // GOOD: Use specific assertions
    @Test
    void goodTest4() {
        assertThat("Hello World").startsWith("Hello");
        assertEquals(5, 2 + 3);
    }
}

