import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.testng.ITestContext;
import org.testng.ITestListener;
import org.testng.ITestResult;

public class TestContextListener implements ITestListener {

    private static final Logger log = LoggerFactory.getLogger(TestContextListener.class);

    @Override
    public void onTestStart(ITestResult result) {
        log.info("Starting test: {}", result.getName());
        // Add to Allure
        Allure.label("testMethod", result.getName());

        // Add test parameters if any
        Object[] params = result.getParameters();
        if (params.length > 0) {
            Allure.addAttachment("Test Parameters", 
                "text/plain", 
                Arrays.toString(params));
        }
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        log.info("Test passed: {}", result.getName());

        // Record execution time
        long duration = result.getEndMillis() - result.getStartMillis();
        Allure.addAttachment("Execution Time", 
            "text/plain", 
            duration + " ms");
    }

    @Override
    public void onTestFailure(ITestResult result) {
        log.error("Test failed: {}", result.getName(), result.getThrowable());

        // Add full stack trace to report
        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);
        result.getThrowable().printStackTrace(pw);
        Allure.addAttachment("Error Stacktrace", 
            "text/plain", 
            sw.toString());
    }

    @Override
    public void onFinish(ITestContext context) {
        log.info("Test suite finished. Total passed: {}, failed: {}, skipped: {}",
            context.getPassedTests().size(),
            context.getFailedTests().size(),
            context.getSkippedTests().size());

        // Generate summary for Allure
        Allure.addAttachment("Suite Summary", "text/plain", String.format("""
            Suite: %s
            Passed: %d
            Failed: %d
            Skipped: %d
            Duration: %d ms
            """,
            context.getName(),
            context.getPassedTests().size(),
            context.getFailedTests().size(),
            context.getSkippedTests().size(),
            context.getEndDate().getTime() - context.getStartDate().getTime()
        ));
    }
}

// ===========================================
// BAD: Hard-coded sleep (brittle and inefficient)
// ===========================================
public void loginWithSleep() throws InterruptedException {
    driver.get("https://example.com");

    Thread.sleep(5000); // Bad: What if page loads in 2 sec? What if it takes 10 sec?

    driver.findElement(By.id("username")).sendKeys("user");
    Thread.sleep(2000); // Even worse: Accumulated delays
    driver.findElement(By.id("password")).sendKeys("pass");
    Thread.sleep(3000);
    driver.findElement(By.id("login")).click();
}

// ===========================================
// GOOD: Conditional wait (efficient and reliable)
// ===========================================
public void loginWithWait() {
    driver.get("https://example.com");

    WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));

    wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("username")))
        .sendKeys("user");

    driver.findElement(By.id("password")).sendKeys("pass");

    wait.until(ExpectedConditions.elementToBeClickable(By.id("login")))
        .click();
}

import org.openqa.selenium.*;
import org.openqa.selenium.chrome.ChromeDriver;
import java.time.Duration;

public class ImplicitWaitExample {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();

        // Set implicit wait - applies to all findElement/findElements calls
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(10));

        // Also set page load timeout and script timeout
        driver.manage().timeouts().pageLoadTimeout(Duration.ofSeconds(30));
        driver.manage().timeouts().scriptTimeout(Duration.ofSeconds(10));

        try {
            driver.get("https://example.com");

            // This call will wait up to 10 seconds for the element to appear in DOM
            // If it appears at second 3, it returns immediately
            // If it never appears, throws NoSuchElementException after 10 seconds
            WebElement username = driver.findElement(By.id("username"));
            username.sendKeys("user");

            // This call also uses the same 10-second implicit wait
            WebElement password = driver.findElement(By.id("password"));
            password.sendKeys("pass");

        } finally {
            driver.quit();
        }
    }
}

// ===========================================
// LIMITATIONS OF IMPLICIT WAIT
// ===========================================
// The following will NOT work with implicit wait alone:

// Problem 1: Element is present but hidden
// This will return immediately (element is in DOM) but then throw
// ElementNotInteractableException when you try to click
WebElement hiddenButton = driver.findElement(By.id("hidden-btn"));
hiddenButton.click(); // May fail

// Problem 2: Element is present but disabled
WebElement disabledButton = driver.findElement(By.id("disabled-btn"));
disabledButton.click(); // May fail

// Problem 3: Waiting for element to disappear (like a loading spinner)
// Implicit wait doesn't help with negative conditions

import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.WebDriverWait;
import org.openqa.selenium.support.ui.ExpectedConditions;
import java.time.Duration;

public class ExplicitWaitComplete {

    private WebDriver driver;
    private WebDriverWait wait;

    public void setup() {
        driver = new ChromeDriver();
        // Initialize wait with 10-second timeout
        wait = new WebDriverWait(driver, Duration.ofSeconds(10));

        // Optional: Configure polling interval (default is 500ms)
        wait.pollingEvery(Duration.ofMillis(250));

        // Optional: Ignore specific exceptions during wait
        wait.ignoring(NoSuchElementException.class);
        wait.ignoring(StaleElementReferenceException.class);
    }

    public void testAllExpectedConditions() {
        driver.get("https://example.com");

        // ===========================================
        // 1. Wait for element to be present in DOM (but maybe hidden)
        // ===========================================
        WebElement usernameField = wait.until(
            ExpectedConditions.presenceOfElementLocated(By.id("username"))
        );

        // ===========================================
        // 2. Wait for element to be visible (present and displayed)
        // ===========================================
        WebElement visibleElement = wait.until(
            ExpectedConditions.visibilityOfElementLocated(By.id("header"))
        );

        // ===========================================
        // 3. Wait for element to be clickable (visible and enabled)
        // ===========================================
        WebElement loginButton = wait.until(
            ExpectedConditions.elementToBeClickable(By.id("loginBtn"))
        );
        loginButton.click();

        // ===========================================
        // 4. Wait for element to contain specific text
        // ===========================================
        wait.until(
            ExpectedConditions.textToBePresentInElementLocated(
                By.id("status"), "Success"
            )
        );

        // ===========================================
        // 5. Wait for element to be selected (checkbox/radio)
        // ===========================================
        wait.until(
            ExpectedConditions.elementToBeSelected(By.id("agreeCheckbox"))
        );

        // ===========================================
        // 6. Wait for element to disappear (invisibility)
        // ===========================================
        wait.until(
            ExpectedConditions.invisibilityOfElementLocated(By.id("loadingSpinner"))
        );

        // ===========================================
        // 7. Wait for an alert to be present
        // ===========================================
        Alert alert = wait.until(ExpectedConditions.alertIsPresent());
        alert.accept();

        // ===========================================
        // 8. Wait for page title to contain specific text
        // ===========================================
        wait.until(
            ExpectedConditions.titleContains("Dashboard")
        );

        // ===========================================
        // 9. Wait for URL to contain specific text
        // ===========================================
        wait.until(
            ExpectedConditions.urlContains("/dashboard")
        );

        // ===========================================
        // 10. Wait for number of windows to be a specific count
        // ===========================================
        wait.until(
            ExpectedConditions.numberOfWindowsToBe(2)
        );

        // ===========================================
        // 11. Wait for frame to be available and switch to it
        // ===========================================
        wait.until(
            ExpectedConditions.frameToBeAvailableAndSwitchToIt("frameName")
        );

        // ===========================================
        // 12. Combining multiple conditions
        // ===========================================
        wait.until(
            ExpectedConditions.and(
                ExpectedConditions.visibilityOfElementLocated(By.id("field1")),
                ExpectedConditions.visibilityOfElementLocated(By.id("field2"))
            )
        );

        // ===========================================
        // 13. OR condition (either one is true)
        // ===========================================
        wait.until(
            ExpectedConditions.or(
                ExpectedConditions.textToBePresentInElementLocated(By.id("status"), "Success"),
                ExpectedConditions.textToBePresentInElementLocated(By.id("error"), "Error")
            )
        );
    }

    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
    }
}

import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.FluentWait;
import org.openqa.selenium.support.ui.Wait;
import java.time.Duration;
import java.util.function.Function;

public class FluentWaitExamples {

    public void basicFluentWaitExample() {
        WebDriver driver = new ChromeDriver();

        // Create FluentWait instance
        Wait<WebDriver> wait = new FluentWait<>(driver)
            .withTimeout(Duration.ofSeconds(30))        // Max wait time
            .pollingEvery(Duration.ofMillis(500))       // Check every 500ms
            .ignoring(NoSuchElementException.class)     // Keep polling if element not found
            .ignoring(StaleElementReferenceException.class)
            .withMessage("Element not found within 30 seconds"); // Custom error message

        // Use the wait
        WebElement element = wait.until(new Function<WebDriver, WebElement>() {
            public WebElement apply(WebDriver driver) {
                return driver.findElement(By.id("dynamicElement"));
            }
        });

        // Lambda version (cleaner)
        WebElement element2 = wait.until(d -> d.findElement(By.id("dynamicElement")));

        element.click();
    }

    public void customConditionExample() {
        WebDriver driver = new ChromeDriver();

        Wait<WebDriver> wait = new FluentWait<>(driver)
            .withTimeout(Duration.ofSeconds(20))
            .pollingEvery(Duration.ofMillis(200))
            .ignoring(NoSuchElementException.class);

        // Custom condition: Wait for element to have a specific attribute value
        WebElement element = wait.until(d -> {
            WebElement el = d.findElement(By.id("progressBar"));
            String style = el.getAttribute("style");
            if (style != null && style.contains("width: 100%")) {
                return el; // Condition met, return the element
            }
            return null; // Condition not met, keep waiting
        });

        // Another custom condition: Wait for page to be fully loaded
        Boolean pageLoaded = wait.until(d -> 
            ((JavascriptExecutor) d).executeScript("return document.readyState")
                .equals("complete")
        );
    }

    public void waitingForAjaxComplete() {
        WebDriver driver = new ChromeDriver();

        Wait<WebDriver> wait = new FluentWait<>(driver)
            .withTimeout(Duration.ofSeconds(30))
            .pollingEvery(Duration.ofMillis(500));

        // Wait for jQuery to finish all AJAX calls
        Boolean ajaxComplete = wait.until(d -> {
            JavascriptExecutor js = (JavascriptExecutor) d;
            // Check if jQuery is defined and if there are active AJAX calls
            Boolean jQueryDefined = (Boolean) js.executeScript(
                "return typeof jQuery !== 'undefined'");
            if (!jQueryDefined) {
                return true; // No jQuery, nothing to wait for
            }
            Long activeConnections = (Long) js.executeScript(
                "return jQuery.active");
            return activeConnections == 0;
        });

        System.out.println("AJAX complete: " + ajaxComplete);
    }

    public void waitingForAngular() {
        WebDriver driver = new ChromeDriver();

        Wait<WebDriver> wait = new FluentWait<>(driver)
            .withTimeout(Duration.ofSeconds(30))
            .pollingEvery(Duration.ofMillis(500));

        // Wait for Angular to finish its work
        Boolean angularReady = wait.until(d -> {
            JavascriptExecutor js = (JavascriptExecutor) d;
            return (Boolean) js.executeScript(
                "return window.getAllAngularTestabilities ? " +
                "window.getAllAngularTestabilities().every(t => t.isStable()) : true"
            );
        });
    }

    public void waitingForElementWithRetry() {
        WebDriver driver = new ChromeDriver();

        // FluentWait with retry on specific failures
        Wait<WebDriver> wait = new FluentWait<>(driver)
            .withTimeout(Duration.ofSeconds(10))
            .pollingEvery(Duration.ofMillis(200))
            .ignoring(NoSuchElementException.class)
            .ignoring(ElementNotInteractableException.class)
            .ignoring(StaleElementReferenceException.class);

        // This will retry even if the element is found but not interactable yet
        WebElement button = wait.until(d -> {
            WebElement el = d.findElement(By.id("submitBtn"));
            if (el.isDisplayed() && el.isEnabled()) {
                return el;
            }
            return null;
        });

        button.click();
    }
}

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import java.time.Duration;

public class WaitConfigurationBestPractice {

    public WebDriver createDriver() {
        WebDriver driver = new ChromeDriver();

        // Set implicit wait to 0 (disable it) - recommended for explicit-wait-only strategy
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(0));

        // Still useful to set page load timeout
        driver.manage().timeouts().pageLoadTimeout(Duration.ofSeconds(30));

        // Set script timeout for async JavaScript
        driver.manage().timeouts().scriptTimeout(Duration.ofSeconds(10));

        return driver;
    }

    // Helper method to get a configured wait instance
    public WebDriverWait getWait(WebDriver driver, int timeoutSeconds) {
        return new WebDriverWait(driver, Duration.ofSeconds(timeoutSeconds));
    }

    // Even better: Centralize wait configuration in a utility class
    public static class WaitUtils {
        private static final int DEFAULT_TIMEOUT = 10;

        public static WebElement waitForElementVisible(WebDriver driver, By locator) {
            return new WebDriverWait(driver, Duration.ofSeconds(DEFAULT_TIMEOUT))
                .until(ExpectedConditions.visibilityOfElementLocated(locator));
        }

        public static WebElement waitForElementClickable(WebDriver driver, By locator) {
            return new WebDriverWait(driver, Duration.ofSeconds(DEFAULT_TIMEOUT))
                .until(ExpectedConditions.elementToBeClickable(locator));
        }

        public static boolean waitForElementInvisible(WebDriver driver, By locator) {
            return new WebDriverWait(driver, Duration.ofSeconds(DEFAULT_TIMEOUT))
                .until(ExpectedConditions.invisibilityOfElementLocated(locator));
        }

        // Overload with custom timeout
        public static WebElement waitForElementVisible(WebDriver driver, By locator, int timeoutSeconds) {
            return new WebDriverWait(driver, Duration.ofSeconds(timeoutSeconds))
                .until(ExpectedConditions.visibilityOfElementLocated(locator));
        }
    }
}

import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.WebDriverWait;
import org.openqa.selenium.support.ui.ExpectedConditions;
import java.time.Duration;

public class PageLoadWait {

    private WebDriver driver;

    // ===========================================
    // METHOD 1: Using pageLoadTimeout (set once)
    // ===========================================
    public void setupPageLoadTimeout() {
        driver.manage().timeouts().pageLoadTimeout(Duration.ofSeconds(30));
        // get() will throw TimeoutException if page doesn't load in 30 seconds
    }

    // ===========================================
    // METHOD 2: Wait for document.readyState
    // ===========================================
    public void waitForDocumentReady() {
        new WebDriverWait(driver, Duration.ofSeconds(30))
            .until(d -> ((JavascriptExecutor) d)
                .executeScript("return document.readyState")
                .equals("complete"));
    }

    // ===========================================
    // METHOD 3: Wait for specific page elements
    // ===========================================
    public void waitForPageElements() {
        // After login, wait for dashboard-specific element
        new WebDriverWait(driver, Duration.ofSeconds(10))
            .until(ExpectedConditions.presenceOfElementLocated(By.id("dashboard")));
    }

    // ===========================================
    // METHOD 4: Wait for no pending AJAX calls
    // ===========================================
    public void waitForAjax() {
        new WebDriverWait(driver, Duration.ofSeconds(30))
            .until(d -> {
                JavascriptExecutor js = (JavascriptExecutor) d;
                // For jQuery
                Object jQueryActive = js.executeScript("return window.jQuery ? jQuery.active : 0");
                if (jQueryActive instanceof Long && (Long)jQueryActive > 0) {
                    return false;
                }
                // For fetch/XHR (more complex - would need to intercept)
                return true;
            });
    }

    // ===========================================
    // METHOD 5: Comprehensive page ready check
    // ===========================================
    public boolean isPageReady() {
        JavascriptExecutor js = (JavascriptExecutor) driver;

        // Check document ready state
        String readyState = js.executeScript("return document.readyState").toString();
        if (!"complete".equals(readyState)) {
            return false;
        }

        // Check for jQuery if present
        Boolean jQueryDefined = (Boolean) js.executeScript("return typeof jQuery !== 'undefined'");
        if (jQueryDefined) {
            Long activeConnections = (Long) js.executeScript("return jQuery.active");
            if (activeConnections > 0) {
                return false;
            }
        }

        // Check for Angular if present
        Boolean angularDefined = (Boolean) js.executeScript(
            "return typeof angular !== 'undefined' || typeof getAllAngularTestabilities !== 'undefined'");
        if (angularDefined) {
            // Angular-specific checks
            Boolean angularReady = (Boolean) js.executeScript(
                "return window.getAllAngularTestabilities ? " +
                "window.getAllAngularTestabilities().every(t => t.isStable()) : true");
            if (!angularReady) {
                return false;
            }
        }

        return true;
    }
}

import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.WebDriverWait;
import org.openqa.selenium.support.ui.ExpectedConditions;
import java.time.Duration;
import java.util.List;

public class DynamicContentWait {

    private WebDriver driver;
    private WebDriverWait wait;

    public DynamicContentWait() {
        driver = new ChromeDriver();
        wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    // ===========================================
    // Scenario: Table loads row by row via AJAX
    // ===========================================
    public void waitForTableToLoad(int expectedRows) {
        // Wait for the table container to appear
        wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("data-table")));

        // Then wait for the expected number of rows
        wait.until(d -> {
            List<WebElement> rows = d.findElements(By.cssSelector("#data-table tbody tr"));
            return rows.size() >= expectedRows;
        });
    }

    // ===========================================
    // Scenario: Loading spinner appears then disappears
    // ===========================================
    public void waitForLoadingSpinner() {
        // First, wait for spinner to appear (if it's not immediate)
        try {
            wait.withTimeout(Duration.ofSeconds(3))
                .until(ExpectedConditions.visibilityOfElementLocated(By.id("spinner")));
        } catch (TimeoutException e) {
            // Spinner never appeared - maybe loading was instant
            return;
        }

        // Then wait for spinner to disappear
        wait.until(ExpectedConditions.invisibilityOfElementLocated(By.id("spinner")));
    }

    // ===========================================
    // Scenario: Progress bar reaches 100%
    // ===========================================
    public void waitForProgressBar() {
        wait.until(d -> {
            WebElement progressBar = d.findElement(By.id("progress"));
            String style = progressBar.getAttribute("style");
            if (style != null && style.contains("width: 100%")) {
                return true;
            }
            return false;
        });
    }

    // ===========================================
    // Scenario: Element's text changes over time
    // ===========================================
    public void waitForTextToChange(By locator, String initialText) {
        wait.until(d -> {
            String currentText = d.findElement(locator).getText();
            return !currentText.equals(initialText);
        });
    }

    // ===========================================
    // Scenario: Wait for an element to have a specific attribute value
    // ===========================================
    public void waitForAttribute(By locator, String attribute, String expectedValue) {
        wait.until(d -> {
            String actualValue = d.findElement(locator).getAttribute(attribute);
            return expectedValue.equals(actualValue);
        });
    }

    // ===========================================
    // Scenario: Wait for a specific element to be stale (page refresh)
    // ===========================================
    public void waitForPageRefresh() {
        WebElement someElement = driver.findElement(By.id("some-element"));

        // Trigger refresh
        driver.navigate().refresh();

        // Wait for the old element to become stale
        wait.until(ExpectedConditions.stalenessOf(someElement));

        // Then wait for the new version to appear
        wait.until(ExpectedConditions.presenceOfElementLocated(By.id("some-element")));
    }
}

import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.ExpectedCondition;
import javax.annotation.Nullable;
import java.util.List;

public class CustomExpectedConditions {

    // ===========================================
    // Condition: Element has a specific CSS class
    // ===========================================
    public static ExpectedCondition<Boolean> elementHasClass(By locator, String cssClass) {
        return new ExpectedCondition<Boolean>() {
            @Override
            public Boolean apply(WebDriver driver) {
                WebElement element = driver.findElement(locator);
                String classes = element.getAttribute("class");
                return classes != null && classes.contains(cssClass);
            }

            @Override
            public String toString() {
                return String.format("element '%s' to have class '%s'", locator, cssClass);
            }
        };
    }

    // ===========================================
    // Condition: Element's value attribute equals expected
    // ===========================================
    public static ExpectedCondition<Boolean> elementValueIs(By locator, String expectedValue) {
        return new ExpectedCondition<Boolean>() {
            @Override
            public Boolean apply(WebDriver driver) {
                String actualValue = driver.findElement(locator).getAttribute("value");
                return expectedValue.equals(actualValue);
            }

            @Override
            public String toString() {
                return String.format("element '%s' value to be '%s'", locator, expectedValue);
            }
        };
    }

    // ===========================================
    // Condition: Number of elements matching a locator
    // ===========================================
    public static ExpectedCondition<List<WebElement>> numberOfElementsToBe(
            By locator, int expectedCount) {
        return new ExpectedCondition<List<WebElement>>() {
            @Override
            public List<WebElement> apply(WebDriver driver) {
                List<WebElement> elements = driver.findElements(locator);
                return elements.size() == expectedCount ? elements : null;
            }

            @Override
            public String toString() {
                return String.format("number of elements matching '%s' to be %d", 
                    locator, expectedCount);
            }
        };
    }

    // ===========================================
    // Condition: Page has loaded all images
    // ===========================================
    public static ExpectedCondition<Boolean> allImagesLoaded() {
        return new ExpectedCondition<Boolean>() {
            @Override
            public Boolean apply(WebDriver driver) {
                JavascriptExecutor js = (JavascriptExecutor) driver;
                return (Boolean) js.executeScript(
                    "return Array.from(document.images).every(img => img.complete)"
                );
            }

            @Override
            public String toString() {
                return "all images to be loaded";
            }
        };
    }

    // ===========================================
    // Condition: Element's text matches a regex pattern
    // ===========================================
    public static ExpectedCondition<Boolean> textMatchesPattern(
            By locator, String regexPattern) {
        return new ExpectedCondition<Boolean>() {
            @Override
            public Boolean apply(WebDriver driver) {
                String text = driver.findElement(locator).getText();
                return text != null && text.matches(regexPattern);
            }

            @Override
            public String toString() {
                return String.format("text of '%s' to match pattern '%s'", 
                    locator, regexPattern);
            }
        };
    }

    // ===========================================
    // Condition: Element is both visible and has specific text
    // ===========================================
    public static ExpectedCondition<WebElement> visibilityOfElementWithText(
            By locator, String expectedText) {
        return new ExpectedCondition<WebElement>() {
            @Override
            public WebElement apply(WebDriver driver) {
                WebElement element = driver.findElement(locator);
                if (element.isDisplayed() && element.getText().contains(expectedText)) {
                    return element;
                }
                return null;
            }

            @Override
            public String toString() {
                return String.format("visibility of element '%s' with text containing '%s'", 
                    locator, expectedText);
            }
        };
    }

    // ===========================================
    // USAGE EXAMPLE
    // ===========================================
    public void useCustomConditions() {
        WebDriver driver = new ChromeDriver();
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));

        // Use custom condition
        wait.until(CustomExpectedConditions.elementHasClass(
            By.id("status"), "success"));

        wait.until(CustomExpectedConditions.elementValueIs(
            By.id("counter"), "100"));

        List<WebElement> rows = wait.until(CustomExpectedConditions.numberOfElementsToBe(
            By.cssSelector("table tr"), 5));

        wait.until(CustomExpectedConditions.allImagesLoaded());

        wait.until(CustomExpectedConditions.textMatchesPattern(
            By.id("order-id"), "ORD-\\d{6}"));
    }
}

package com.example.utils;

import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.ExpectedCondition;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import java.time.Duration;
import java.util.List;

public class WaitUtility {

    private WebDriver driver;
    private int defaultTimeout;
    private int pollingInterval;

    public WaitUtility(WebDriver driver) {
        this(driver, 10, 500);
    }

    public WaitUtility(WebDriver driver, int defaultTimeoutSeconds, int pollingIntervalMillis) {
        this.driver = driver;
        this.defaultTimeout = defaultTimeoutSeconds;
        this.pollingInterval = pollingIntervalMillis;
    }

    private WebDriverWait getWait() {
        return getWait(defaultTimeout);
    }

    private WebDriverWait getWait(int timeoutSeconds) {
        return new WebDriverWait(driver, Duration.ofSeconds(timeoutSeconds))
            .pollingEvery(Duration.ofMillis(pollingInterval))
            .ignoring(NoSuchElementException.class)
            .ignoring(StaleElementReferenceException.class);
    }

    // ===========================================
    // Standard conditions
    // ===========================================

    public WebElement waitForVisible(By locator) {
        return getWait().until(ExpectedConditions.visibilityOfElementLocated(locator));
    }

    public WebElement waitForVisible(By locator, int timeoutSeconds) {
        return getWait(timeoutSeconds).until(
            ExpectedConditions.visibilityOfElementLocated(locator));
    }

    public WebElement waitForClickable(By locator) {
        return getWait().until(ExpectedConditions.elementToBeClickable(locator));
    }

    public WebElement waitForClickable(WebElement element) {
        return getWait().until(ExpectedConditions.elementToBeClickable(element));
    }

    public boolean waitForInvisible(By locator) {
        return getWait().until(ExpectedConditions.invisibilityOfElementLocated(locator));
    }

    public boolean waitForTextPresent(By locator, String text) {
        return getWait().until(
            ExpectedConditions.textToBePresentInElementLocated(locator, text));
    }

    public Alert waitForAlert() {
        return getWait().until(ExpectedConditions.alertIsPresent());
    }

    // ===========================================
    // Custom conditions
    // ===========================================

    public boolean waitForAttribute(By locator, String attribute, String value) {
        return getWait().until(d -> {
            WebElement el = d.findElement(locator);
            return value.equals(el.getAttribute(attribute));
        });
    }

    public boolean waitForPageReady() {
        return getWait().until(d -> {
            JavascriptExecutor js = (JavascriptExecutor) d;
            return "complete".equals(js.executeScript("return document.readyState"));
        });
    }

    public boolean waitForAjaxComplete() {
        return getWait(30).until(d -> {
            JavascriptExecutor js = (JavascriptExecutor) d;
            // Check for jQuery
            Boolean jQueryDefined = (Boolean) js.executeScript(
                "return typeof jQuery !== 'undefined'");
            if (jQueryDefined) {
                Long active = (Long) js.executeScript("return jQuery.active");
                if (active > 0) return false;
            }
            return true;
        });
    }

    public <T> T waitForCondition(ExpectedCondition<T> condition) {
        return getWait().until(condition);
    }

    public <T> T waitForCondition(ExpectedCondition<T> condition, int timeoutSeconds) {
        return getWait(timeoutSeconds).until(condition);
    }
}

