import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.firefox.FirefoxOptions;
import org.openqa.selenium.edge.EdgeOptions;
import org.openqa.selenium.safari.SafariOptions;
import java.util.HashMap;
import java.util.Map;

public class BrowserOptionsComplete {

    // ===========================================
    // Chrome Options
    // ===========================================
    public ChromeOptions getChromeOptions(boolean headless, String deviceName) {
        ChromeOptions options = new ChromeOptions();

        // Common options
        if (headless) {
            options.addArguments("--headless");
            options.addArguments("--window-size=1920,1080");
        }

        // Performance and stability
        options.addArguments("--disable-gpu");
        options.addArguments("--no-sandbox");
        options.addArguments("--disable-dev-shm-usage");
        options.addArguments("--disable-extensions");
        options.addArguments("--disable-notifications");
        options.addArguments("--disable-popup-blocking");

        // Language and locale
        options.addArguments("--lang=en-US");
        options.addArguments("--accept-lang=en-US");

        // Mobile emulation
        if (deviceName != null && !deviceName.isEmpty()) {
            Map<String, Object> mobileEmulation = new HashMap<>();
            mobileEmulation.put("deviceName", deviceName);
            options.setExperimentalOption("mobileEmulation", mobileEmulation);
        }

        // Additional preferences
        Map<String, Object> prefs = new HashMap<>();
        prefs.put("download.default_directory", "/path/to/downloads");
        prefs.put("profile.default_content_setting_values.notifications", 2);
        options.setExperimentalOption("prefs", prefs);

        return options;
    }

    // ===========================================
    // Firefox Options
    // ===========================================
    public FirefoxOptions getFirefoxOptions(boolean headless) {
        FirefoxOptions options = new FirefoxOptions();

        if (headless) {
            options.addArguments("--headless");
            options.addArguments("--width=1920");
            options.addArguments("--height=1080");
        }

        // Firefox preferences
        options.addPreference("browser.download.folderList", 2);
        options.addPreference("browser.download.dir", "/path/to/downloads");
        options.addPreference("browser.helperApps.neverAsk.saveToDisk", "application/pdf,text/csv");
        options.addPreference("pdfjs.disabled", true);

        // Disable various features for consistency
        options.addPreference("dom.webnotifications.enabled", false);
        options.addPreference("media.autoplay.default", 5);

        return options;
    }

    // ===========================================
    // Edge Options (Chromium-based)
    // ===========================================
    public EdgeOptions getEdgeOptions(boolean headless) {
        EdgeOptions options = new EdgeOptions();

        if (headless) {
            options.addArguments("--headless");
            options.addArguments("--window-size=1920,1080");
        }

        options.addArguments("--disable-gpu");
        options.addArguments("--disable-extensions");
        options.addArguments("--disable-notifications");

        return options;
    }

    // ===========================================
    // Safari Options (limited)
    // ===========================================
    public SafariOptions getSafariOptions() {
        SafariOptions options = new SafariOptions();

        // Safari has limited configuration options
        // Important: Safari requires enabling 'Remote Automation' in Develop menu

        return options;
    }
}

