import org.testng.annotations.*;
import java.net.URL;
import java.util.HashMap;

public class BrowserStackTest {

    private WebDriver driver;

    @BeforeMethod
    @Parameters({"browser", "browserVersion", "os", "osVersion", "deviceName"})
    public void setup(String browser, String browserVersion, String os, 
                     String osVersion, String deviceName) throws Exception {

        // BrowserStack credentials (best from environment variables)
        String username = System.getenv("BROWSERSTACK_USERNAME");
        String accessKey = System.getenv("BROWSERSTACK_ACCESS_KEY");

        DesiredCapabilities caps = new DesiredCapabilities();

        // Basic capabilities
        caps.setCapability("browserName", browser);
        caps.setCapability("browserVersion", browserVersion);

        // OS and device
        HashMap<String, Object> browserstackOptions = new HashMap<>();
        browserstackOptions.put("os", os);
        browserstackOptions.put("osVersion", osVersion);

        if (deviceName != null && !deviceName.isEmpty()) {
            browserstackOptions.put("deviceName", deviceName);
            browserstackOptions.put("realMobile", "true");
        }

        // Build and project info
        browserstackOptions.put("buildName", "Cross-Browser Regression Suite");
        browserstackOptions.put("projectName", "E-Commerce App");
        browserstackOptions.put("sessionName", "Test on " + browser + " " + browserVersion);

        // Test settings
        browserstackOptions.put("local", "false");
        browserstackOptions.put("debug", "true");
        browserstackOptions.put("networkLogs", "true");
        browserstackOptions.put("consoleLogs", "info");
        browserstackOptions.put("video", "true");

        caps.setCapability("bstack:options", browserstackOptions);

        // Connect to BrowserStack hub
        String hubUrl = "https://" + username + ":" + accessKey + "@hub-cloud.browserstack.com/wd/hub";
        driver = new RemoteWebDriver(new URL(hubUrl), caps);
    }

    @Test
    public void testLoginFunctionality() {
        driver.get("https://example.com");

        // Your test logic here
        String title = driver.getTitle();
        assert title.contains("Example");

        // Mark test status in BrowserStack dashboard
        markTestStatus("passed", "Login test passed");
    }

    private void markTestStatus(String status, String reason) {
        JavascriptExecutor jse = (JavascriptExecutor) driver;
        jse.executeScript(String.format(
            "browserstack_executor: {\"action\": \"setSessionStatus\", \"arguments\": {\"status\":\"%s\", \"reason\":\"%s\"}}",
            status, reason));
    }

    @AfterMethod
    public void teardown() {
        if (driver != null) {
            driver.quit();
        }
    }
}

