// In your test, you can execute JavaScript to detect browser features

public class BrowserFeatureChecker {

    private WebDriver driver;

    public boolean supportsDateInput() {
        return (Boolean) ((JavascriptExecutor) driver).executeScript(
            "var input = document.createElement('input');" +
            "input.setAttribute('type', 'date');" +
            "return input.type !== 'text';"
        );
    }

    public boolean supportsWebP() {
        return (Boolean) ((JavascriptExecutor) driver).executeScript(
            "var canvas = document.createElement('canvas');" +
            "return canvas.toDataURL('image/webp').indexOf('data:image/webp') === 0;"
        );
    }

    public String getBrowserInfo() {
        return (String) ((JavascriptExecutor) driver).executeScript(
            "return navigator.userAgent;"
        );
    }

    public boolean isMobileBrowser() {
        return (Boolean) ((JavascriptExecutor) driver).executeScript(
            "return /Mobi|Android|iPhone|iPad|iPod/i.test(navigator.userAgent);"
        );
    }

    public void testWithFeatureDetection() {
        if (supportsDateInput()) {
            // Use standard date picker interaction
            driver.findElement(By.cssSelector("input[type='date']")).sendKeys("2024-01-01");
        } else {
            // Use fallback method (e.g., JavaScript to set value)
            ((JavascriptExecutor) driver).executeScript(
                "document.querySelector('input[type=\"date\"]').value = '2024-01-01';"
            );
        }
    }
}

import org.openqa.selenium.Capabilities;
import org.openqa.selenium.remote.RemoteWebDriver;

public class ConditionalBrowserLogic {

    private WebDriver driver;
    private String browserName;
    private String browserVersion;
    private String platform;

    @BeforeMethod
    public void setup() {
        // Get browser info from driver capabilities
        Capabilities caps = ((RemoteWebDriver) driver).getCapabilities();
        browserName = caps.getBrowserName().toLowerCase();
        browserVersion = caps.getBrowserVersion();
        platform = caps.getPlatformName().toString();

        System.out.println("Running on: " + browserName + " " + browserVersion + " on " + platform);
    }

    @Test
    public void testWithBrowserConditionals() {
        driver.get("https://example.com");

        // Different wait strategies per browser
        if (browserName.contains("safari")) {
            // Safari is often slower, use longer timeouts
            WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(15));
            wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("main")));
        } else {
            WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
            wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("main")));
        }

        // Different assertions based on browser
        String title = driver.getTitle();

        if (browserName.contains("firefox")) {
            // Firefox might have slightly different title due to rendering
            Assert.assertTrue(title.startsWith("Example") || title.startsWith("example"));
        } else {
            Assert.assertTrue(title.contains("Example"));
        }

        // Skip certain tests on specific browsers
        assumeTrue(!(browserName.contains("safari") && browserVersion.startsWith("12")),
            "Skipping test on Safari 12 due to known issue with WebDriver");
    }

    @Test
    public void testMobileSpecificFeatures() {
        if (platform.contains("ios") || platform.contains("android")) {
            // Test touch-specific interactions
            performTouchGestures();
        } else {
            // Test desktop interactions
            performMouseActions();
        }
    }

    private void performTouchGestures() {
        // Mobile-specific test logic
    }

    private void performMouseActions() {
        // Desktop-specific test logic
    }
}

