import org.junit.jupiter.api.*;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.junit.jupiter.api.parallel.ResourceAccessMode;

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public class JUnit5ParallelTest {

    @BeforeAll
    void init() {
        System.out.println("Setup - Thread: " + Thread.currentThread().getName());
    }

    // ===========================================
    // Method 1: Using configuration defaults
    // ===========================================
    @Test
    void testOne() throws InterruptedException {
        System.out.println("Test 1 started - Thread: " + Thread.currentThread().getName());
        Thread.sleep(2000);
        System.out.println("Test 1 completed");
    }

    @Test
    void testTwo() throws InterruptedException {
        System.out.println("Test 2 started - Thread: " + Thread.currentThread().getName());
        Thread.sleep(2000);
        System.out.println("Test 2 completed");
    }

    // ===========================================
    // Method 2: Explicit execution mode
    // ===========================================
    @Test
    @Execution(ExecutionMode.CONCURRENT)  // Override default
    void testThree() {
        System.out.println("Test 3 running concurrently");
    }

    @Test
    @Execution(ExecutionMode.SAME_THREAD)  // Force sequential
    void testFour() {
        System.out.println("Test 4 must run alone");
    }

    // ===========================================
    // Method 3: Synchronizing shared resources
    // ===========================================
    private static int sharedCounter = 0;

    @Test
    @ResourceLock(value = "counter", mode = ResourceAccessMode.READ_WRITE)
    void testIncrementCounter() {
        synchronized (this) {
            sharedCounter++;
            System.out.println("Counter: " + sharedCounter);
        }
    }

    @Test
    @ResourceLock(value = "database", mode = ResourceAccessMode.READ)
    void testReadDatabase() {
        // Multiple tests can read from DB concurrently
    }

    @Test
    @ResourceLock(value = "database", mode = ResourceAccessMode.READ_WRITE)
    void testWriteDatabase() {
        // Only one test can write at a time
    }

    // ===========================================
    // Method 4: Parallel parameterized tests
    // ===========================================
    @ParameterizedTest
    @ValueSource(strings = {"chrome", "firefox", "edge", "safari"})
    @Execution(ExecutionMode.CONCURRENT)
    void testOnBrowser(String browser) throws InterruptedException {
        System.out.println("Testing on " + browser + " - Thread: " + 
            Thread.currentThread().getName());
        Thread.sleep(1000);
    }
}

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.remote.RemoteWebDriver;
import org.testng.annotations.*;
import java.net.URL;
import java.time.Duration;

public class GridParallelTest {

    private WebDriver driver;
    private String nodeUrl;

    @BeforeMethod
    @Parameters({"browser", "version", "platform", "node"})
    public void setup(String browser, String version, String platform, String node) throws Exception {
        this.nodeUrl = node;

        // Create capabilities based on browser
        MutableCapabilities capabilities = new MutableCapabilities();
        capabilities.setCapability("browserName", browser);
        capabilities.setCapability("browserVersion", version);

        // Platform-specific settings
        if (platform != null && !platform.isEmpty()) {
            capabilities.setCapability("platformName", platform);
        }

        // Browser-specific options
        if ("chrome".equalsIgnoreCase(browser)) {
            ChromeOptions options = new ChromeOptions();
            options.addArguments("--disable-gpu");
            options.addArguments("--no-sandbox");
            options.addArguments("--disable-dev-shm-usage");
            capabilities = options.merge(capabilities);
        }

        // Connect to Grid
        driver = new RemoteWebDriver(new URL(node + "/wd/hub"), capabilities);
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(10));
        driver.manage().window().maximize();
    }

    @Test
    public void testGoogleSearch() {
        driver.get("https://www.google.com");

        WebElement searchBox = driver.findElement(By.name("q"));
        searchBox.sendKeys("Selenium Grid");
        searchBox.submit();

        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        wait.until(ExpectedConditions.titleContains("Selenium Grid"));

        System.out.println(Thread.currentThread().getName() + 
            " - Test completed on " + driver.getCurrentUrl());
    }

    @AfterMethod
    public void teardown() {
        if (driver != null) {
            driver.quit();
        }
    }
}

