package com.company.core.dataproviders;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import org.testng.annotations.DataProvider;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Database Data Provider with connection pooling
 * for efficient test data retrieval from databases.
 */
public class DatabaseDataProvider {

    private static HikariDataSource dataSource;

    static {
        // Initialize connection pool
        HikariConfig config = new HikariConfig();
        config.setJdbcUrl(System.getProperty("db.url", "jdbc:mysql://localhost:3306/testdb"));
        config.setUsername(System.getProperty("db.user", "testuser"));
        config.setPassword(System.getProperty("db.password", "testpass"));
        config.setMaximumPoolSize(10);
        config.setMinimumIdle(2);
        config.setConnectionTimeout(30000);
        config.setIdleTimeout(600000);
        config.setMaxLifetime(1800000);

        dataSource = new HikariDataSource(config);
    }

    /**
     * Execute SQL query and return results as Object[][]
     */
    public static Object[][] executeQuery(String sql, String... params) {
        List<Object[]> results = new ArrayList<>();

        try (Connection conn = dataSource.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            // Set parameters if any
            for (int i = 0; i < params.length; i++) {
                stmt.setString(i + 1, params[i]);
            }

            try (ResultSet rs = stmt.executeQuery()) {
                ResultSetMetaData metaData = rs.getMetaData();
                int columnCount = metaData.getColumnCount();

                while (rs.next()) {
                    Object[] row = new Object[columnCount];
                    for (int i = 1; i <= columnCount; i++) {
                        row[i - 1] = rs.getObject(i);
                    }
                    results.add(row);
                }
            }

        } catch (SQLException e) {
            throw new RuntimeException("Database query failed: " + sql, e);
        }

        return results.toArray(new Object[0][]);
    }

    /**
     * DataProvider for user data from database
     */
    @DataProvider(name = "dbUsers")
    public static Object[][] provideUsers() {
        String sql = "SELECT username, email, role, active FROM users WHERE active = ?";
        return executeQuery(sql, "true");
    }

    /**
     * DataProvider for product catalog
     */
    @DataProvider(name = "dbProducts")
    public static Object[][] provideProducts() {
        String sql = "SELECT product_id, name, price, category FROM products WHERE price > ?";
        return executeQuery(sql, "10.00");
    }

    /**
     * Clean up resources
     */
    public static void closeDataSource() {
        if (dataSource != null && !dataSource.isClosed()) {
            dataSource.close();
        }
    }
}

