import org.testng.annotations.DataProvider;
import org.testng.annotations.Test;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;

public class TestNGDataProviderPatterns {

    // ===========================================
    // Pattern 1: Simple 2D Array
    // ===========================================
    @DataProvider(name = "simpleData")
    public Object[][] simpleData() {
        return new Object[][]{
            {"user1", "pass1"},
            {"user2", "pass2"},
            {"user3", "pass3"}
        };
    }

    // ===========================================
    // Pattern 2: Mixed Data Types
    // ===========================================
    @DataProvider(name = "mixedTypes")
    public Object[][] mixedTypes() {
        return new Object[][]{
            {"admin", 123, true, 45.67},
            {"guest", 456, false, 89.01}
        };
    }

    // ===========================================
    // Pattern 3: Using Objects
    // ===========================================
    @DataProvider(name = "objectData")
    public Object[][] objectData() {
        return new Object[][]{
            {new User("alice", "alice@test.com", true)},
            {new User("bob", "bob@test.com", false)}
        };
    }

    // ===========================================
    // Pattern 4: Method-Specific DataProvider
    // ===========================================
    @DataProvider(name = "methodAware")
    public Object[][] methodAwareDataProvider(Method method) {
        switch(method.getName()) {
            case "testLogin":
                return new Object[][]{
                    {"admin", "admin123"},
                    {"user", "user123"}
                };
            case "testSearch":
                return new Object[][]{
                    {"laptop", 10},
                    {"phone", 5}
                };
            default:
                return new Object[][]{{}};
        }
    }

    // ===========================================
    // Pattern 5: Iterator-based DataProvider (for large datasets)
    // ===========================================
    @DataProvider(name = "iteratorData")
    public Iterator<Object[]> iteratorDataProvider() {
        List<Object[]> data = new ArrayList<>();
        for (int i = 0; i < 1000; i++) {
            data.add(new Object[]{"user" + i, "pass" + i});
        }
        return data.iterator();
    }

    // ===========================================
    // Pattern 6: Parallel DataProvider
    // ===========================================
    @DataProvider(name = "parallelData", parallel = true)
    public Object[][] parallelDataProvider() {
        return new Object[][]{
            {"data1"}, {"data2"}, {"data3"}, {"data4"}
        };
    }

    // ===========================================
    // Pattern 7: DataProvider with Inheritance
    // ===========================================
    public static class BaseDataProvider {
        @DataProvider(name = "baseData")
        public Object[][] baseData() {
            return new Object[][]{
                {"base1"}, {"base2"}
            };
        }
    }

    public static class ExtendedDataProvider extends BaseDataProvider {
        @DataProvider(name = "extendedData")
        public Object[][] extendedData() {
            return new Object[][]{
                {"extended1"}, {"extended2"}
            };
        }
    }

    // ===========================================
    // Test Methods
    // ===========================================

    @Test(dataProvider = "simpleData")
    public void testSimpleData(String user, String pass) {
