    private static final Random random = new Random();

    // ===========================================
    // User Data Generators
    // ===========================================

    public static class UserGenerator {

        public static String randomUsername() {
            return faker.name().username().toLowerCase();
        }

        public static String randomEmail() {
            return faker.internet().emailAddress();
        }

        public static String randomPassword() {
            return RandomStringUtils.randomAlphanumeric(10) + 
                   "!" + RandomStringUtils.randomNumeric(2);
        }

        public static String randomPhoneNumber() {
            return faker.phoneNumber().phoneNumber();
        }

        public static LocalDate randomBirthDate() {
            return faker.date().birthday().toInstant()
                .atZone(ZoneId.systemDefault())
                .toLocalDate();
        }

        public static TestUser createRandomUser() {
            return new TestUser(
                randomUsername(),
                randomEmail(),
                randomPassword(),
                randomPhoneNumber(),
                randomBirthDate()
            );
        }

        public static List<TestUser> createRandomUsers(int count) {
            List<TestUser> users = new ArrayList<>();
            for (int i = 0; i < count; i++) {
                users.add(createRandomUser());
            }
            return users;
        }
    }

    // ===========================================
    // Product Data Generators
    // ===========================================

    public static class ProductGenerator {

        private static final String[] CATEGORIES = {
            "Electronics", "Clothing", "Books", "Home & Garden", "Sports", "Toys"
        };

        private static final String[] PRODUCT_PREFIXES = {
            "Premium", "Deluxe", "Basic", "Pro", "Ultra", "Mini", "Max"
        };

        public static String randomProductName() {
            return PRODUCT_PREFIXES[random.nextInt(PRODUCT_PREFIXES.length)] + " " +
                   faker.commerce().productName();
        }

        public static double randomPrice(double min, double max) {
            return min + (max - min) * random.nextDouble();
        }

        public static String randomCategory() {
            return CATEGORIES[random.nextInt(CATEGORIES.length)];
        }

        public static String randomSKU() {
            return "SKU-" + RandomStringUtils.randomAlphanumeric(8).toUpperCase();
        }

        public static int randomStock(int max) {
            return random.nextInt(max);
        }

        public static TestProduct createRandomProduct() {
            return new TestProduct(
                randomProductName(),
                randomPrice(5.0, 999.99),
                randomCategory(),
                randomSKU(),
                randomStock(1000)
            );
        }
    }

