    // ===========================================
    // Boundary Value Generators
    // ===========================================

    public static class BoundaryGenerator {

        public static List<Integer> getBoundaryValues(int min, int max) {
            return Arrays.asList(
                min - 1,  // Below minimum
                min,      // Minimum
                min + 1,  // Just above minimum
                (min + max) / 2,  // Middle
                max - 1,  // Just below maximum
                max,      // Maximum
                max + 1   // Above maximum
            );
        }

        public static List<String> getStringBoundaries(int minLength, int maxLength) {
            return Arrays.asList(
                RandomStringUtils.randomAlphabetic(minLength - 1),  // Too short
                RandomStringUtils.randomAlphabetic(minLength),      // Minimum
                RandomStringUtils.randomAlphabetic(minLength + 1),  // Just above min
                RandomStringUtils.randomAlphabetic(maxLength - 1),  // Just below max
                RandomStringUtils.randomAlphabetic(maxLength),      // Maximum
                RandomStringUtils.randomAlphabetic(maxLength + 1)   // Too long
            );
        }
    }

