public class PairwiseTest {

    @DataProvider(name = "filterTests")
    public Object[][] provideFilterTests() {
        Map<String, List<String>> params = new LinkedHashMap<>();
        params.put("category", Arrays.asList("Electronics", "Clothing", "Books", "Toys"));
        params.put("priceRange", Arrays.asList("$0-50", "$50-100", "$100-500", "$500+"));
        params.put("rating", Arrays.asList("1+", "2+", "3+", "4+"));
        params.put("sortBy", Arrays.asList("price", "rating", "newest"));

        List<Map<String, String>> combinations = PairwiseGenerator.generatePairwise(params);
        System.out.println("Full combinations: 4×4×4×3 = 192");
        System.out.println("Pairwise combinations: " + combinations.size());

        return PairwiseGenerator.toDataProvider(combinations);
    }

