using TechTalk.SpecFlow;
using Allure.Net.Commons;

namespace Tests.UI.Hooks
{
    [Binding]
    public class TestHooks
    {
        private readonly IObjectContainer _objectContainer;
        private readonly ScenarioContext _scenarioContext;
        private IWebDriver _driver;
        private ITestLogger _logger;
        private IScreenshotHelper _screenshotHelper;

        public TestHooks(IObjectContainer objectContainer, ScenarioContext scenarioContext)
        {
            _objectContainer = objectContainer;
            _scenarioContext = scenarioContext;
        }

        [BeforeTestRun]
        public static void BeforeTestRun()
        {
            // Initialize test run
            TestLogger.InitializeTestRun();

            // Create report directories
            Directory.CreateDirectory("./allure-results");
            Directory.CreateDirectory("./screenshots");
            Directory.CreateDirectory("./test-logs");

            Console.WriteLine("Test Run Started");
        }

        [BeforeScenario]
        public void BeforeScenario()
        {
            // Initialize services
            var serviceProvider = _objectContainer.Resolve<IServiceProvider>();
            var driverFactory = serviceProvider.GetService<IWebDriverFactory>();
            _logger = serviceProvider.GetService<ITestLogger>();
            _screenshotHelper = serviceProvider.GetService<IScreenshotHelper>();

            // Create WebDriver
            _driver = driverFactory.CreateDriver();
            _objectContainer.RegisterInstanceAs(_driver);
            _scenarioContext.Set(_driver, "Driver");

            // Initialize test context
            var scenarioName = _scenarioContext.ScenarioInfo.Title;
            var tags = string.Join(", ", _scenarioContext.ScenarioInfo.Tags);

            _logger.InitializeTestLogger(scenarioName);
            _logger.Info($"Starting scenario: {scenarioName}");
            _logger.Info($"Tags: {tags}");

            // Allure setup
            AllureLifecycle.Instance.UpdateTestCase(testCase =>
            {
                testCase.labels.Add(new Label { name = "feature", value = _scenarioContext.ScenarioInfo.FeatureInfo.Title });
                testCase.labels.Add(new Label { name = "story", value = scenarioName });
                testCase.labels.AddRange(_scenarioContext.ScenarioInfo.Tags.Select(tag => new Label { name = "tag", value = tag }));
            });
        }

        [BeforeStep]
        public void BeforeStep()
        {
            var stepInfo = _scenarioContext.StepContext.StepInfo.Text;
            _logger.Info($"Executing step: {stepInfo}");

            // Wait for page stability before each step
            var customWait = new CustomWait(_driver, _logger);
            customWait.WaitForPageToLoad(10);
        }

        [AfterStep]
        public void AfterStep()
        {
            var stepInfo = _scenarioContext.StepContext.StepInfo.Text;

            if (_scenarioContext.TestError != null)
            {
                _logger.Error($"Step failed: {stepInfo}", _scenarioContext.TestError);

                // Capture screenshot on step failure
                try
                {
                    var screenshotPath = _screenshotHelper.CaptureScreenshot(_driver, $"step_failure_{DateTime.Now:yyyyMMdd_HHmmss}");
                    _logger.Info($"Screenshot captured: {screenshotPath}");

                    // Attach to Allure report
                    AllureLifecycle.Instance.AddAttachment(
                        $"Step Failure - {stepInfo}", 
                        "image/png", 
                        _screenshotHelper.CaptureScreenshotAsBytes(_driver)
                    );
                }
                catch (Exception ex)
                {
                    _logger.Error("Failed to capture screenshot", ex);
                }
            }
            else
            {
                _logger.Info($"Step completed: {stepInfo}");
            }
        }

        [AfterScenario]
        public void AfterScenario()
        {
            var scenarioName = _scenarioContext.ScenarioInfo.Title;

            try
            {
                if (_scenarioContext.TestError != null)
                {
                    _logger.Error($"Scenario FAILED: {scenarioName}", _scenarioContext.TestError);

                    // Capture final screenshot on scenario failure
                    var screenshotPath = _screenshotHelper.CaptureScreenshot(_driver, $"scenario_failure_{DateTime.Now:yyyyMMdd_HHmmss}");

                    // Attach page source to Allure
                    AllureLifecycle.Instance.AddAttachment(
                        $"Page Source - {scenarioName}", 
                        "text/html", 
                        _driver.PageSource
                    );

                    // Attach browser logs if available
                    AttachBrowserLogs();
                }
                else
                {
                    _logger.Info($"Scenario PASSED: {scenarioName}");
                }

                // Log scenario duration
                _logger.Info($"Scenario completed: {scenarioName}");
            }
            finally
            {
                // Cleanup WebDriver
                var driverFactory = _objectContainer.Resolve<IWebDriverFactory>();
                driverFactory.DisposeDriver(_driver);

                // Cleanup test logger
                _logger.CleanupTestLogger();
            }
        }

        [AfterTestRun]
        public static void AfterTestRun()
        {
            // Generate final reports
            TestLogger.FinalizeTestRun();

            Console.WriteLine("Test Run Completed");

            // Optional: Trigger report generation
            GenerateAllureReport();
        }

        private void AttachBrowserLogs()
        {
            try
            {
                var logs = _driver.Manage().Logs;
                var browserLogs = logs.GetLog(LogType.Browser);

                if (browserLogs.Any())
                {
                    var logContent = string.Join("\n", browserLogs.Select(log => $"{log.Timestamp}: {log.Message}"));
                    AllureLifecycle.Instance.AddAttachment("Browser Logs", "text/plain", logContent);
                }
            }
            catch (Exception ex)
            {
                _logger.Warn($"Failed to capture browser logs: {ex.Message}");
            }
        }

        private static void GenerateAllureReport()
        {
            try
            {
                // This would typically be done via command line
                // allure serve allure-results
                Console.WriteLine("Allure report generation completed");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to generate Allure report: {ex.Message}");
            }
        }
    }
}

