using System.Data.SqlClient;
using Dapper;
using Microsoft.Extensions.Configuration;

namespace Tests.Database
{
    public abstract class DatabaseTestBase : IDisposable
    {
        protected SqlConnection Connection;
        protected readonly IConfiguration Configuration;

        protected DatabaseTestBase(IConfiguration configuration)
        {
            Configuration = configuration;
            InitializeConnection();
        }

        private void InitializeConnection()
        {
            var connectionString = Configuration.GetConnectionString("TestDatabase");
            Connection = new SqlConnection(connectionString);
            Connection.Open();
        }

        protected T QuerySingle<T>(string sql, object parameters = null)
        {
            return Connection.QuerySingle<T>(sql, parameters);
        }

        protected List<T> Query<T>(string sql, object parameters = null)
        {
            return Connection.Query<T>(sql, parameters).ToList();
        }

        protected int Execute(string sql, object parameters = null)
        {
            return Connection.Execute(sql, parameters);
        }

        protected T ExecuteScalar<T>(string sql, object parameters = null)
        {
            return Connection.ExecuteScalar<T>(sql, parameters);
        }

        protected void CleanupTestData(string tableName, string whereClause = "")
        {
            var sql = $"DELETE FROM {tableName}";
            if (!string.IsNullOrEmpty(whereClause))
            {
                sql += $" WHERE {whereClause}";
            }
            Execute(sql);
        }

        protected int GetRecordCount(string tableName, string whereClause = "")
        {
            var sql = $"SELECT COUNT(*) FROM {tableName}";
            if (!string.IsNullOrEmpty(whereClause))
            {
                sql += $" WHERE {whereClause}";
            }
            return ExecuteScalar<int>(sql);
        }

        public void Dispose()
        {
            Connection?.Close();
            Connection?.Dispose();
        }
    }

    // User Database Tests
    public class UserDatabaseTests : DatabaseTestBase
    {
        public UserDatabaseTests(IConfiguration configuration) : base(configuration) { }

        public User GetUserById(int userId)
        {
            const string sql = @"
                SELECT UserId, Username, Email, FirstName, LastName, IsActive, CreatedDate
                FROM Users WHERE UserId = @UserId";

            return QuerySingle<User>(sql, new { UserId = userId });
        }

        public List<User> GetActiveUsers()
        {
            const string sql = @"
                SELECT UserId, Username, Email, FirstName, LastName, IsActive, CreatedDate
                FROM Users WHERE IsActive = 1";

            return Query<User>(sql);
        }

        public void DeactivateUser(int userId)
        {
            const string sql = @"
                UPDATE Users 
                SET IsActive = 0, ModifiedDate = GETDATE()
                WHERE UserId = @UserId";

            Execute(sql, new { UserId = userId });
        }

        public int CreateUser(User user)
        {
            const string sql = @"
                INSERT INTO Users (Username, Email, FirstName, LastName, IsActive, CreatedDate)
                OUTPUT INSERTED.UserId
                VALUES (@Username, @Email, @FirstName, @LastName, @IsActive, GETDATE())";

            return ExecuteScalar<int>(sql, user);
        }

        // Database verification in UI tests
        public void VerifyUserInDatabaseAfterRegistration(string username)
        {
            const string sql = @"SELECT COUNT(*) FROM Users WHERE Username = @Username";
            var userCount = ExecuteScalar<int>(sql, new { Username = username });

            userCount.Should().Be(1, $"User {username} should exist in database after registration");
        }
