// MobileTestBase.cs
using OpenQA.Selenium.Appium;
using OpenQA.Selenium.Appium.Android;
using OpenQA.Selenium.Appium.iOS;
using OpenQA.Selenium.Appium.Enums;

namespace Tests.Mobile
{
    public abstract class MobileTestBase : IDisposable
    {
        protected AppiumDriver Driver;
        protected Platform Platform;

        protected MobileTestBase(Platform platform)
        {
            Platform = platform;
            InitializeDriver();
        }

        private void InitializeDriver()
        {
            var appiumOptions = new AppiumOptions();

            switch (Platform)
            {
                case Platform.Android:
                    ConfigureAndroidOptions(appiumOptions);
                    Driver = new AndroidDriver(new Uri("http://localhost:4723/wd/hub"), appiumOptions);
                    break;
                case Platform.iOS:
                    ConfigureIOSOptions(appiumOptions);
                    Driver = new IOSDriver(new Uri("http://localhost:4723/wd/hub"), appiumOptions);
                    break;
                default:
                    throw new NotSupportedException($"Platform {Platform} is not supported");
            }

            Driver.Manage().Timeouts().ImplicitWait = TimeSpan.FromSeconds(10);
        }

        private void ConfigureAndroidOptions(AppiumOptions options)
        {
            options.AddAdditionalAppiumOption(MobileCapabilityType.PlatformName, "Android");
            options.AddAdditionalAppiumOption(MobileCapabilityType.PlatformVersion, "11.0");
            options.AddAdditionalAppiumOption(MobileCapabilityType.DeviceName, "Android Emulator");
            options.AddAdditionalAppiumOption(MobileCapabilityType.AutomationName, "UiAutomator2");
            options.AddAdditionalAppiumOption("appPackage", "com.example.app");
            options.AddAdditionalAppiumOption("appActivity", "com.example.app.MainActivity");
            options.AddAdditionalAppiumOption("noReset", false);
            options.AddAdditionalAppiumOption("fullReset", false);
        }

        private void ConfigureIOSOptions(AppiumOptions options)
        {
            options.AddAdditionalAppiumOption(MobileCapabilityType.PlatformName, "iOS");
            options.AddAdditionalAppiumOption(MobileCapabilityType.PlatformVersion, "15.0");
            options.AddAdditionalAppiumOption(MobileCapabilityType.DeviceName, "iPhone Simulator");
            options.AddAdditionalAppiumOption(MobileCapabilityType.AutomationName, "XCUITest");
            options.AddAdditionalAppiumOption("bundleId", "com.example.app");
            options.AddAdditionalAppiumOption("noReset", false);
        }

        protected void Swipe(Direction direction)
        {
            var size = Driver.Manage().Window.Size;
            int startX, startY, endX, endY;

            switch (direction)
            {
                case Direction.Up:
                    startX = size.Width / 2;
                    startY = (int)(size.Height * 0.8);
                    endX = startX;
                    endY = (int)(size.Height * 0.2);
                    break;
                case Direction.Down:
                    startX = size.Width / 2;
                    startY = (int)(size.Height * 0.2);
                    endX = startX;
                    endY = (int)(size.Height * 0.8);
                    break;
                case Direction.Left:
                    startX = (int)(size.Width * 0.8);
                    startY = size.Height / 2;
                    endX = (int)(size.Width * 0.2);
                    endY = startY;
                    break;
                case Direction.Right:
                    startX = (int)(size.Width * 0.2);
                    startY = size.Height / 2;
                    endX = (int)(size.Width * 0.8);
                    endY = startY;
                    break;
                default:
                    throw new ArgumentException("Invalid swipe direction");
            }

            var touchAction = new TouchAction(Driver);
            touchAction.Press(startX, startY)
                      .Wait(500)
                      .MoveTo(endX, endY)
                      .Release()
                      .Perform();
        }

        protected void TapElement(AppiumWebElement element)
        {
            var touchAction = new TouchAction(Driver);
            touchAction.Tap(element).Perform();
        }

        protected void HideKeyboard()
        {
            try
            {
                Driver.HideKeyboard();
            }
            catch (Exception)
            {
                // Keyboard might not be visible
            }
        }

        public void Dispose()
        {
            Driver?.Quit();
            Driver?.Dispose();
        }
    }

    public enum Platform
    {
        Android,
        iOS
    }

    public enum Direction
    {
        Up,
        Down,
        Left,
        Right
    }

    // Mobile Page Objects
    public class MobileLoginPage : MobileTestBase
    {
        public MobileLoginPage(Platform platform) : base(platform) { }

        private By UsernameField => Platform == Platform.Android ? 
            By.Id("com.example.app:id/username") : 
            By.XPath("//XCUIElementTypeTextField[@name='username']");

        private By PasswordField => Platform == Platform.Android ? 
            By.Id("com.example.app:id/password") : 
            By.XPath("//XCUIElementTypeSecureTextField[@name='password']");

        private By LoginButton => Platform == Platform.Android ? 
            By.Id("com.example.app:id/login_button") : 
            By.XPath("//XCUIElementTypeButton[@name='Login']");

        public void EnterUsername(string username)
        {
            var element = (AppiumWebElement)Driver.FindElement(UsernameField);
            element.SendKeys(username);
        }

        public void EnterPassword(string password)
        {
            var element = (AppiumWebElement)Driver.FindElement(PasswordField);
            element.SendKeys(password);
        }

        public MobileDashboardPage ClickLogin()
        {
            var element = (AppiumWebElement)Driver.FindElement(LoginButton);
            TapElement(element);
            return new MobileDashboardPage(Platform);
        }

        public MobileDashboardPage Login(string username, string password)
        {
            EnterUsername(username);
            EnterPassword(password);
            HideKeyboard();
            return ClickLogin();
        }
    }
}

// PerformanceMonitor.cs
using OpenQA.Selenium;
using OpenQA.Selenium.DevTools;
using OpenQA.Selenium.DevTools.V114.Performance;
using System.Diagnostics;

namespace Tests.Performance
{
    public interface IPerformanceMonitor
    {
        Task StartMonitoring();
        Task<PerformanceMetrics> StopMonitoring();
        Task<PageLoadMetrics> MeasurePageLoad(string pageUrl);
        Task<ApiResponseMetrics> MeasureApiCall(Func<Task> apiCall);
        void AssertPerformanceThresholds(PerformanceMetrics metrics);
    }

    public class PerformanceMonitor : IPerformanceMonitor
    {
        private readonly IWebDriver _driver;
        private IDevToolsSession _devToolsSession;
        private bool _isMonitoring = false;

        public PerformanceMonitor(IWebDriver driver)
        {
            _driver = driver;
        }

        public async Task StartMonitoring()
        {
            if (_driver is IDevTools)
            {
                var devTools = (IDevTools)_driver;
                _devToolsSession = devTools.GetDevToolsSession();

                await _devToolsSession.SendCommand<EnableCommandSettings>(new EnableCommandSettings());
                _isMonitoring = true;
            }
        }

        public async Task<PerformanceMetrics> StopMonitoring()
        {
            if (!_isMonitoring || _devToolsSession == null)
                return new PerformanceMetrics();

            var metricsResponse = await _devToolsSession.SendCommand<GetMetricsCommandSettings, GetMetricsCommandResponse>(
                new GetMetricsCommandSettings());

            _isMonitoring = false;

            return new PerformanceMetrics
            {
                Metrics = metricsResponse.Metrics.ToDictionary(m => m.Name, m => m.Value),
                Timestamp = DateTime.UtcNow
            };
        }

        public async Task<PageLoadMetrics> MeasurePageLoad(string pageUrl)
        {
            var stopwatch = Stopwatch.StartNew();

            await StartMonitoring();

            // Navigate to page
            _driver.Navigate().GoToUrl(pageUrl);

            // Wait for page to be completely loaded
            var wait = new WebDriverWait(_driver, TimeSpan.FromSeconds(30));
            wait.Until(d => ((IJavaScriptExecutor)d).ExecuteScript("return document.readyState").Equals("complete"));

            stopwatch.Stop();

            var performanceMetrics = await StopMonitoring();

            return new PageLoadMetrics
            {
                LoadTime = stopwatch.ElapsedMilliseconds,
                PerformanceMetrics = performanceMetrics,
                Url = pageUrl
            };
        }

        public async Task<ApiResponseMetrics> MeasureApiCall(Func<Task> apiCall)
        {
            var stopwatch = Stopwatch.StartNew();

            try
            {
                await apiCall();
            }
            finally
            {
                stopwatch.Stop();
            }

            return new ApiResponseMetrics
            {
                ResponseTime = stopwatch.ElapsedMilliseconds,
                Timestamp = DateTime.UtcNow
            };
        }

        public void AssertPerformanceThresholds(PerformanceMetrics metrics)
        {
            // Define performance thresholds
            const long maxPageLoadTime = 3000; // 3 seconds
            const long maxFirstContentfulPaint = 1500; // 1.5 seconds
            const long maxLargestContentfulPaint = 2500; // 2.5 seconds

            if (metrics.Metrics.TryGetValue("FirstContentfulPaint", out var fcp))
            {
                fcp.Should().BeLessThan(maxFirstContentfulPaint, 
                    $"First Contentful Paint should be less than {maxFirstContentfulPaint}ms");
            }

            if (metrics.Metrics.TryGetValue("LargestContentfulPaint", out var lcp))
            {
                lcp.Should().BeLessThan(maxLargestContentfulPaint, 
                    $"Largest Contentful Paint should be less than {maxLargestContentfulPaint}ms");
            }
        }
    }

    public class PerformanceMetrics
    {
        public Dictionary<string, double> Metrics { get; set; } = new Dictionary<string, double>();
        public DateTime Timestamp { get; set; }
    }

    public class PageLoadMetrics
    {
        public long LoadTime { get; set; }
        public PerformanceMetrics PerformanceMetrics { get; set; }
        public string Url { get; set; }
    }

    public class ApiResponseMetrics
    {
        public long ResponseTime { get; set; }
        public DateTime Timestamp { get; set; }
    }

    // Performance-aware UI Tests
    public class PerformanceAwareLoginTests
    {
        private readonly LoginPage _loginPage;
        private readonly IPerformanceMonitor _performanceMonitor;

        public PerformanceAwareLoginTests(LoginPage loginPage, IPerformanceMonitor performanceMonitor)
        {
            _loginPage = loginPage;
            _performanceMonitor = performanceMonitor;
        }

        public async Task<PageLoadMetrics> TestLoginWithPerformanceMeasurement(string username, string password)
        {
            // Measure page load performance
            var pageLoadMetrics = await _performanceMonitor.MeasurePageLoad(_loginPage.GetPageUrl());

            // Perform login
            var dashboard = _loginPage.Login(username, password);

            // Verify functionality
            dashboard.IsDashboardLoaded().Should().BeTrue();

            // Assert performance thresholds
            _performanceMonitor.AssertPerformanceThresholds(pageLoadMetrics.PerformanceMetrics);

            return pageLoadMetrics;
        }
    }
}

