    }

    public string GetBaseUrl(string page = null)
    {
        var envConfig = _configService.GetSection<EnvironmentConfiguration>("Framework:Environment");

        if (!string.IsNullOrEmpty(page) && envConfig.Urls.ContainsKey(page))
        {
            return envConfig.Urls[page];
        }

        return envConfig.BaseUrl;
    }

    public string GetApiUrl(string endpoint = null)
    {
        var envConfig = _configService.GetSection<EnvironmentConfiguration>("Framework:Environment");
        var apiUrl = envConfig.ApiUrl;

        if (!string.IsNullOrEmpty(endpoint))
        {
            apiUrl = $"{apiUrl.TrimEnd('/')}/{endpoint.TrimStart('/')}";
        }

        return apiUrl;
    }

    public bool IsProduction()
    {
        return _configService.IsEnvironment("Production");
    }

    public bool IsDevelopment()
    {
        return _configService.IsEnvironment("Development");
    }

    public void ValidateEnvironment()
    {
        var envConfig = _configService.GetSection<EnvironmentConfiguration>("Framework:Environment");

        if (string.IsNullOrEmpty(envConfig.BaseUrl))
        {
            throw new InvalidOperationException("Base URL is not configured for the current environment");
        }

        if (IsProduction() && !envConfig.BaseUrl.StartsWith("https://"))
        {
            throw new InvalidOperationException("Production environment must use HTTPS");
        }
    }
}

// Browser Manager Service
public interface IBrowserManager
{
    IWebDriver CreateBrowser(BrowserType browserType, BrowserOptions options = null);
    void CloseBrowser(IWebDriver driver);
    void CloseAllBrowsers();
    List<BrowserInfo> GetActiveBrowsers();
    void SetWindowSize(IWebDriver driver, WindowSize size);
    void TakeBrowserSnapshot(IWebDriver driver, string snapshotName);
}

public class BrowserManager : IBrowserManager
{
    private readonly List<BrowserSession> _activeSessions;
    private readonly IWebDriverFactory _driverFactory;
    private readonly ITestLogger _logger;

    public BrowserManager(IWebDriverFactory driverFactory, ITestLogger logger)
    {
        _activeSessions = new List<BrowserSession>();
        _driverFactory = driverFactory;
        _logger = logger;
    }

    public IWebDriver CreateBrowser(BrowserType browserType, BrowserOptions options = null)
    {
        options ??= new BrowserOptions();

        var driver = _driverFactory.CreateDriver(browserType.ToString(), options);

        var session = new BrowserSession
        {
            Driver = driver,
            BrowserType = browserType,
            StartTime = DateTime.Now,
            SessionId = Guid.NewGuid().ToString()
        };

        _activeSessions.Add(session);

        // Apply browser settings
        SetWindowSize(driver, options.WindowSize);

        if (options.EnableLogging)
        {
            EnableBrowserLogging(driver);
        }

        _logger.Info($"Created {browserType} browser session: {session.SessionId}");

        return driver;
    }

    public void CloseBrowser(IWebDriver driver)
    {
        var session = _activeSessions.FirstOrDefault(s => s.Driver == driver);
        if (session != null)
        {
            try
            {
                _driverFactory.DisposeDriver(driver);
                _activeSessions.Remove(session);
                _logger.Info($"Closed browser session: {session.SessionId}");
            }
            catch (Exception ex)
            {
                _logger.Error($"Error closing browser session {session.SessionId}", ex);
            }
        }
    }

    public void CloseAllBrowsers()
    {
        foreach (var session in _activeSessions.ToList())
        {
            CloseBrowser(session.Driver);
        }
    }

    public List<BrowserInfo> GetActiveBrowsers()
    {
        return _activeSessions.Select(s => new BrowserInfo
        {
            SessionId = s.SessionId,
            BrowserType = s.BrowserType,
            StartTime = s.StartTime,
            Url = s.Driver.Url
        }).ToList();
    }

    public void SetWindowSize(IWebDriver driver, WindowSize size)
    {
        if (size != null)
        {
            driver.Manage().Window.Size = new System.Drawing.Size(size.Width, size.Height);
        }
    }

    public void TakeBrowserSnapshot(IWebDriver driver, string snapshotName)
    {
        try
        {
            var screenshot = ((ITakesScreenshot)driver).GetScreenshot();
            var screenshotPath = Path.Combine("browser-snapshots", $"{snapshotName}_{DateTime.Now:yyyyMMdd_HHmmss}.png");
            Directory.CreateDirectory(Path.GetDirectoryName(screenshotPath));
            screenshot.SaveAsFile(screenshotPath, ScreenshotImageFormat.Png);

            _logger.Info($"Browser snapshot saved: {screenshotPath}");
        }
        catch (Exception ex)
        {
            _logger.Warn($"Failed to take browser snapshot: {ex.Message}");
        }
    }

    private void EnableBrowserLogging(IWebDriver driver)
    {
        // Enable browser console logging
        var logs = driver.Manage().Logs;
        // Additional logging configuration...
    }
}

