                analysis.put("weaknesses", "Unknown");
                analysis.put("migration_effort", "Unknown");
                analysis.put("recommended_target", "Assess current needs");
        }

        return analysis;
    }

    public static MigrationPlan createMigrationPlan(String sourceFramework, String targetFramework) {
        MigrationPlan plan = new MigrationPlan();
        plan.setSourceFramework(sourceFramework);
        plan.setTargetFramework(targetFramework);

        // Define migration steps based on source and target
        if ("pom".equalsIgnoreCase(sourceFramework) && "bdd".equalsIgnoreCase(targetFramework)) {
            plan.addStep("Phase 1", "Create feature files from existing test cases");
            plan.addStep("Phase 1", "Identify business-readable scenarios");
            plan.addStep("Phase 2", "Create step definitions mapping to existing page methods");
            plan.addStep("Phase 3", "Refactor page objects for better reusability");
            plan.addStep("Phase 4", "Train team on BDD concepts and Gherkin");
            plan.setEstimatedDuration("8-12 weeks");
        } else if ("pom".equalsIgnoreCase(sourceFramework) && "hybrid".equalsIgnoreCase(targetFramework)) {
            plan.addStep("Phase 1", "Identify reusable actions for keyword library");
            plan.addStep("Phase 1", "Design data-driven test structure");
            plan.addStep("Phase 2", "Create keyword repository");
            plan.addStep("Phase 3", "Build test execution engine");
            plan.addStep("Phase 4", "Migrate existing tests to keyword-driven approach");
            plan.setEstimatedDuration("6-10 weeks");
        } else if ("hybrid".equalsIgnoreCase(sourceFramework) && "bdd".equalsIgnoreCase(targetFramework)) {
            plan.addStep("Phase 1", "Map existing keywords to business scenarios");
            plan.addStep("Phase 2", "Create feature files representing business flows");
            plan.addStep("Phase 3", "Build step definitions using existing keywords");
            plan.addStep("Phase 4", "Implement BDD reporting and documentation");
            plan.setEstimatedDuration("4-8 weeks");
        }

        return plan;
    }

    public static class MigrationPlan {
        private String sourceFramework;
        private String targetFramework;
        private Map<String, String> phases = new HashMap<>();
