        public void setEstimatedDuration(String estimatedDuration) {
            this.estimatedDuration = estimatedDuration;
        }

        public void printPlan() {
            System.out.println("=== Migration Plan ===");
            System.out.println("From: " + sourceFramework + " -> To: " + targetFramework);
            System.out.println("Estimated Duration: " + estimatedDuration);
            System.out.println("\nMigration Steps:");
            phases.forEach((phase, step) -> System.out.println(phase + ": " + step));
        }
    }
}

