// Jenkinsfile Example for Test Automation Pipeline
pipeline {
    agent any

    parameters {
        choice(
            name: 'TEST_ENV',
            choices: ['dev', 'qa', 'staging'],
            description: 'Select test environment'
        )
        string(
            name: 'TEST_TAGS',
            defaultValue: '@smoke',
            description: 'Cucumber tags to execute'
        )
        booleanParam(
            name: 'PARALLEL_EXECUTION',
            defaultValue: true,
            description: 'Execute tests in parallel'
        )
    }

    options {
        timeout(time: 30, unit: 'MINUTES')
        buildDiscarder(logRotator(numToKeepStr: '10'))
        disableConcurrentBuilds()
    }

    environment {
        JAVA_HOME = '/usr/lib/jvm/java-11-openjdk'
        MAVEN_HOME = '/usr/share/maven'
        PATH = "${MAVEN_HOME}/bin:${JAVA_HOME}/bin:${PATH}"
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Setup Test Environment') {
            steps {
                script {
                    // Environment-specific setup
                    echo "Setting up ${TEST_ENV} environment"
                    sh '''
                        cp src/test/resources/config-${TEST_ENV}.properties \
                           src/test/resources/config.properties
                    '''
                }
            }
        }

        stage('Execute Tests') {
            steps {
                script {
                    if (params.PARALLEL_EXECUTION) {
                        // Parallel test execution
                        parallelTestExecution()
                    } else {
                        // Sequential test execution
                        sh '''
                            mvn test -Dcucumber.filter.tags="${TEST_TAGS}" \
                                    -Denvironment=${TEST_ENV}
                        '''
                    }
                }
            }
        }
    }

    post {
        always {
            // Always publish test results
            publishHTML([
                allowMissing: false,
                alwaysLinkToLastBuild: true,
                keepAll: true,
                reportDir: 'target/surefire-reports',
                reportFiles: 'index.html',
                reportName: 'Test Report'
            ])

            // Clean workspace
            cleanWs()
        }
        success {
            echo 'Test execution completed successfully!'
        }
        failure {
            echo 'Test execution failed! Check reports for details.'
            // Send notification
            emailext (
                subject: "FAILED: Test Execution Build ${env.BUILD_NUMBER}",
                body: "Test execution failed for environment ${TEST_ENV}.\nBuild URL: ${env.BUILD_URL}",
                to: 'qa-team@company.com'
            )
        }
    }
}

