// Helper methods for parallel execution
def analyzeTestSuite() {
    // Analyze test suite to determine optimal parallelization
    def testCount = sh(script: 'mvn test -DdryRun=true | grep "Tests run:" | tail -1', returnStdout: true)
    def pythonTestCount = sh(script: 'pytest --collect-only -q | wc -l', returnStdout: true).trim()

    def totalTests = testCount.split(':')[1].split(',')[0].toInteger() + pythonTestCount.toInteger()

    // Determine optimal agent count based on test size
    def agentCount = Math.min(Math.max(totalTests / 100, 2), 8)

    // Create test groups for balanced execution
    def groups = []
    def testsPerGroup = Math.ceil(totalTests / agentCount)

    return [
        groups: groups,
        agentCount: agentCount,
        totalTests: totalTests
    ]
}

def getPythonTestGroups() {
    // Analyze Python test structure for optimal grouping
    def testFiles = sh(script: 'find tests/ -name "test_*.py" -type f', returnStdout: true).trim().split('\n')

    def groups = []
    testFiles.each { file ->
        def testCount = sh(script: "pytest ${file} --collect-only -q | wc -l", returnStdout: true).trim().toInteger()
        groups << [
            name: file.replace('/', '-').replace('.py', ''),
            path: file,
            testCount: testCount,
            agent: 'python-agent-' + ((groups.size() % 3) + 1)
        ]
    }

    return groups
}

// TEST SPLITTING AND LOAD BALANCING
pipeline {
    agent any

    parameters {
        choice(
            name: 'SPLIT_STRATEGY',
            choices: ['duration', 'count', 'file', 'smart'],
            description: 'Test splitting strategy'
        )
        string(
            name: 'TARGET_DURATION',
            defaultValue: '600',
            description: 'Target duration per chunk (seconds)'
        )
    }

    stages {
        stage('Test Analysis') {
            steps {
                script {
                    // Analyze test characteristics for optimal splitting
                    def javaAnalysis = analyzeJavaTests()
                    def pythonAnalysis = analyzePythonTests()

                    env.JAVA_TEST_CHUNKS = splitJavaTests(javaAnalysis, params.SPLIT_STRATEGY)
                    env.PYTHON_TEST_CHUNKS = splitPythonTests(pythonAnalysis, params.SPLIT_STRATEGY)

                    echo "Java test chunks: ${env.JAVA_TEST_CHUNKS.size()}"
                    echo "Python test chunks: ${env.PYTHON_TEST_CHUNKS.size()}"
                }
            }
        }

        stage('Balanced Test Execution') {
            parallel {
                // Java balanced execution
                stage('Java - Balanced Chunks') {
                    steps {
                        script {
                            def javaStages = [:]
                            env.JAVA_TEST_CHUNKS.eachWithIndex { chunk, index ->
                                javaStages["Java-Chunk-${index + 1}"] = {
                                    node("java-agent-${(index % 3) + 1}") {
                                        checkout scm

                                        // Execute specific test chunk
                                        if (chunk.testNames) {
                                            sh "mvn test -Dtest='${chunk.testNames.join(\",\")}'"
                                        } else if (chunk.groups) {
                                            sh "mvn test -Dgroups='${chunk.groups.join(\",\")}'"
                                        }

                                        // Record execution metrics
                                        recordChunkMetrics('java', chunk, index)
                                    }
                                }
                            }
                            parallel javaStages
                        }
                    }
                }

                // Python balanced execution
                stage('Python - Balanced Chunks') {
                    steps {
                        script {
                            def pythonStages = [:]
                            env.PYTHON_TEST_CHUNKS.eachWithIndex { chunk, index ->
                                pythonStages["Python-Chunk-${index + 1}"] = {
                                    node("python-agent-${(index % 3) + 1}") {
                                        checkout scm

                                        // Execute specific test chunk
                                        if (chunk.testFiles) {
                                            sh "pytest ${chunk.testFiles.join(' ')} -v --junitxml=reports/python-chunk-${index + 1}.xml"
                                        } else if (chunk.markers) {
                                            sh "pytest -m '${chunk.markers}' -v --junitxml=reports/python-chunk-${index + 1}.xml"
                                        }

                                        // Record execution metrics
                                        recordChunkMetrics('python', chunk, index)
                                    }
                                }
                            }
                            parallel pythonStages
                        }
                    }
                }
            }
        }

        stage('Adaptive Rebalancing') {
            steps {
                script {
                    // Analyze execution times and rebalance if needed
                    def imbalance = checkLoadImbalance()

                    if (imbalance > 0.3) { // 30% imbalance threshold
                        echo "Detected load imbalance: ${imbalance}. Rebalancing..."

                        // Redistribute remaining tests
                        def redistributedChunks = redistributeTests()

                        // Execute redistributed chunks
                        def rebalanceStages = [:]
                        redistributedChunks.eachWithIndex { chunk, index ->
                            rebalanceStages["Rebalance-Chunk-${index + 1}"] = {
                                node("agent-${index + 1}") {
                                    executeRedistributedChunk(chunk)
                                }
                            }
                        }

                        parallel rebalanceStages
                    }
                }
            }
        }
    }

    post {
        always {
            // Generate load balancing report
            sh 'python scripts/generate_balancing_report.py'

            // Archive balancing metrics
            archiveArtifacts artifacts: 'reports/balancing_metrics.json', allowEmptyArchive: true
        }
    }
}

// Test analysis and splitting functions
def analyzeJavaTests() {
    // Get test execution history for duration-based splitting
    def testHistory = readJSON file: 'reports/test_history.json'

    // Collect current test information
    def testList = sh(script: 'mvn test -DdryRun=true -Dtest=**/*Test', returnStdout: true)

    def tests = []
    testList.split('\n').each { line ->
        if (line.contains('Running') && line.contains('Test')) {
            def testName = line.split(' ').find { it.contains('Test') }
            def avgDuration = testHistory.tests.find { it.name == testName }?.avgDuration ?: 30

            tests << [
                name: testName,
                estimatedDuration: avgDuration,
                group: extractTestGroup(testName)
            ]
        }
    }

    return tests
}

def analyzePythonTests() {
    // Analyze Python test structure and durations
    def testFiles = sh(script: 'find tests/ -name "test_*.py" -type f', returnStdout: true).trim().split('\n')

    def tests = []
    testFiles.each { file ->
        def testCount = sh(script: "pytest ${file} --collect-only -q | wc -l", returnStdout: true).trim().toInteger()
        def markers = sh(script: "grep -h '@pytest.mark.' ${file} | head -5", returnStdout: true).trim()

        tests << [
            file: file,
            testCount: testCount,
            markers: extractMarkers(markers),
            estimatedDuration: testCount * 2 // Rough estimate
        ]
    }

    return tests
}

def splitJavaTests(tests, strategy) {
    def chunks = []

    switch(strategy) {
        case 'duration':
            chunks = splitByDuration(tests, params.TARGET_DURATION.toInteger())
            break
        case 'count':
            chunks = splitByCount(tests, Math.ceil(tests.size() / 4))
            break
        case 'file':
            chunks = splitByFileStructure(tests)
            break
        case 'smart':
            chunks = smartSplit(tests)
            break
    }

    return chunks
}

def splitPythonTests(tests, strategy) {
    // Similar implementation for Python tests
    def chunks = []

    switch(strategy) {
        case 'duration':
            def totalDuration = tests.sum { it.estimatedDuration }
            def targetChunks = Math.ceil(totalDuration / params.TARGET_DURATION.toInteger())
            chunks = splitByDuration(tests, params.TARGET_DURATION.toInteger())
            break
        case 'count':
            def totalTests = tests.sum { it.testCount }
            def testsPerChunk = Math.ceil(totalTests / 4)
            chunks = splitByTestCount(tests, testsPerChunk)
            break
        case 'file':
            chunks = splitByPythonModules(tests)
            break
        case 'smart':
            chunks = smartPythonSplit(tests)
            break
    }

    return chunks
}

// Duration-based splitting
def splitByDuration(tests, targetDuration) {
    def chunks = []
    def currentChunk = []
    def currentDuration = 0

    tests.sort { -it.estimatedDuration } // Sort by duration descending

    tests.each { test ->
        if (currentDuration + test.estimatedDuration > targetDuration && currentChunk) {
            chunks << [tests: currentChunk, estimatedDuration: currentDuration]
            currentChunk = []
            currentDuration = 0
        }
        currentChunk << test
        currentDuration += test.estimatedDuration
    }

    if (currentChunk) {
        chunks << [tests: currentChunk, estimatedDuration: currentDuration]
    }

    return chunks
}

// Smart splitting considering dependencies and resources
def smartSplit(tests) {
    def chunks = []

    // Group tests by resource requirements
    def resourceGroups = tests.groupBy { test ->
        if (test.name.contains('Integration') || test.name.contains('Database')) {
            return 'high-resource'
        } else if (test.name.contains('Service')) {
            return 'medium-resource'
        } else {
            return 'low-resource'
        }
    }

    // Distribute high-resource tests evenly
    resourceGroups['high-resource']?.eachWithIndex { test, index ->
        if (!chunks[index]) chunks[index] = []
        chunks[index] << test
    }

    // Distribute remaining tests
    ['medium-resource', 'low-resource'].each { resourceType ->
        resourceGroups[resourceType]?.each { test ->
            def chunk = chunks.min { chunk -> chunk.sum { it.estimatedDuration } }
            chunk << test
        }
    }

    return chunks.collect { chunk -> 
        [tests: chunk, estimatedDuration: chunk.sum { it.estimatedDuration }]
    }
}

