// ADVANCED RETRY MECHANISMS AND FLAKY TEST HANDLING
pipeline {
    agent any

    parameters {
        choice(
            name: 'RETRY_STRATEGY',
            choices: ['none', 'simple', 'smart', 'adaptive'],
            description: 'Test retry strategy'
        )
        string(
            name: 'MAX_RETRIES',
            defaultValue: '3',
            description: 'Maximum retry attempts'
        )
        booleanParam(
            name: 'DETECT_FLAKY_TESTS',
            defaultValue: true,
            description: 'Enable flaky test detection'
        )
    }

    environment {
        FLAKY_TEST_THRESHOLD = '0.3'
        RETRY_DELAY = '5'
    }

    stages {
        stage('Test Execution with Retry') {
            steps {
                script {
                    def testResults = executeTestsWithRetry()
                    env.FAILED_TESTS = testResults.failedTests.join(',')
                    env.FLAKY_CANDIDATES = testResults.flakyCandidates.join(',')
                }
            }
        }

        stage('Flaky Test Analysis') {
            when {
                expression { params.DETECT_FLAKY_TESTS && env.FAILED_TESTS }
            }
            steps {
                script {
                    def failedTestsList = env.FAILED_TESTS.split(',').toList()
                    def flakyAnalysis = analyzeFlakyTests(failedTestsList)

                    if (flakyAnalysis.confirmedFlaky.size() > 0) {
                        echo "Confirmed flaky tests: ${flakyAnalysis.confirmedFlaky}"
                        quarantineFlakyTests(flakyAnalysis.confirmedFlaky)
                        generateFlakyTestReport(flakyAnalysis)
                    }
                }
            }
        }

        stage('Retry Failed Tests') {
            when {
                expression { env.FAILED_TESTS && params.RETRY_STRATEGY != 'none' }
            }
            steps {
                script {
                    def failedTestsList = env.FAILED_TESTS.split(',').toList()
                    def retryResults = retryFailedTests(failedTestsList)
                    updateTestResults(retryResults)
                }
            }
        }
    }

    post {
        always {
            sh 'python scripts/generate_retry_report.py'
            updateTestHistory()
        }

        success {
            script {
                if (env.FLAKY_CANDIDATES) {
                    echo "Potential flaky tests detected: ${env.FLAKY_CANDIDATES}"
                }
            }
        }
    }
}

// Retry strategy implementations
def executeTestsWithRetry() {
    def failedTests = []
    def flakyCandidates = []

    switch(params.RETRY_STRATEGY) {
        case 'simple':
            (failedTests, flakyCandidates) = simpleRetryStrategy()
            break
        case 'smart':
            (failedTests, flakyCandidates) = smartRetryStrategy()
            break
        case 'adaptive':
            (failedTests, flakyCandidates) = adaptiveRetryStrategy()
            break
        default:
            def result = executeTests()
            failedTests = result.failedTests
    }

    return [failedTests: failedTests, flakyCandidates: flakyCandidates]
}

def simpleRetryStrategy() {
    def failedTests = []
    def flakyCandidates = []

    def attempt = 1
    while (attempt <= params.MAX_RETRIES.toInteger()) {
        echo "Test execution attempt ${attempt}"

        def result = executeTests()

        if (attempt == 1) {
            failedTests = result.failedTests
        } else {
            def newlyPassed = failedTests.findAll { !result.failedTests.contains(it) }
            flakyCandidates.addAll(newlyPassed)
            failedTests = result.failedTests
        }

        if (failedTests.empty) break

        attempt++
        if (attempt <= params.MAX_RETRIES.toInteger()) {
            sleep params.RETRY_DELAY.toInteger()
        }
    }

    return [failedTests, flakyCandidates]
}

def smartRetryStrategy() {
    def failedTests = []
    def flakyCandidates = []

    def firstResult = executeTests()
    failedTests = firstResult.failedTests

    if (!failedTests.empty) {
        def failureAnalysis = analyzeFailures(failedTests)
        def retryCandidates = failureAnalysis.findAll { it.flakyProbability > 0.5 }

        if (!retryCandidates.empty) {
            echo "Retrying ${retryCandidates.size()} potentially flaky tests"

            def retryResult = executeSpecificTests(retryCandidates*.testName)

            def newlyPassed = retryCandidates.findAll { candidate ->
                !retryResult.failedTests.contains(candidate.testName)
            }
            flakyCandidates.addAll(newlyPassed*.testName)

            failedTests.removeAll(retryCandidates*.testName)
            failedTests.addAll(retryResult.failedTests)
        }
    }

    return [failedTests, flakyCandidates]
}

def adaptiveRetryStrategy() {
    def failedTests = []
    def flakyCandidates = []

    def testHistory = loadTestHistory()
    def result = executeTests()
    failedTests = result.failedTests

    def attempt = 1
    while (attempt <= params.MAX_RETRIES.toInteger() && !failedTests.empty) {
        def retryConfig = calculateAdaptiveRetryConfig(failedTests, testHistory, attempt)

        if (retryConfig.shouldRetry) {
            echo "Adaptive retry attempt ${attempt} with delay ${retryConfig.delay}s"

            sleep retryConfig.delay

            def retryResult = executeSpecificTests(retryConfig.testsToRetry)

            def newlyPassed = failedTests.findAll { !retryResult.failedTests.contains(it) }
            flakyCandidates.addAll(newlyPassed)

            failedTests = retryResult.failedTests
        }

        attempt++
    }

    return [failedTests, flakyCandidates]
}

// Flaky test detection and handling
def analyzeFlakyTests(failedTests) {
    def analysis = [
        confirmedFlaky: [],
        suspectedFlaky: [],
        stableFailures: []
    ]

    def history = loadTestHistory()

    failedTests.each { testName ->
        def testHistory = history.tests.find { it.name == testName }

        if (testHistory) {
            def flakinessScore = calculateFlakinessScore(testHistory)

            if (flakinessScore > env.FLAKY_TEST_THRESHOLD.toDouble()) {
                analysis.confirmedFlaky << testName
            } else if (flakinessScore > 0.1) {
                analysis.suspectedFlaky << testName
            } else {
                analysis.stableFailures << testName
            }
        } else {
            analysis.suspectedFlaky << testName
        }
    }

    return analysis
}

def quarantineFlakyTests(flakyTests) {
    echo "Quarantining flaky tests: ${flakyTests}"

    if (flakyTests.any { it.contains('.java') }) {
        sh """
            # Add flaky tests to exclusion list
            python scripts/quarantine_java_tests.py ${flakyTests.join(' ')}
        """
    }

    if (flakyTests.any { it.contains('test_') }) {
        sh """
            # Mark flaky tests with @pytest.mark.flaky
            python scripts/quarantine_python_tests.py ${flakyTests.join(' ')}
        """
    }

    writeJSON file: 'reports/quarantined_tests.json', json: [
        timestamp: new Date().format('yyyy-MM-dd HH:mm:ss'),
        quarantinedTests: flakyTests,
        buildNumber: env.BUILD_NUMBER
    ]
}

// Test execution helper methods
def executeTests() {
    def failedTests = []

    try {
        sh 'mvn test -Dtest=**/*Test'
    } catch (Exception e) {
        def javaFailed = parseTestResults('target/surefire-reports')
        failedTests.addAll(javaFailed)
    }

    try {
        sh 'pytest tests/ -v --junitxml=reports/pytest-results.xml'
    } catch (Exception e) {
        def pythonFailed = parseTestResults('reports')
        failedTests.addAll(pythonFailed)
    }

    return [failedTests: failedTests]
}

def executeSpecificTests(testNames) {
    def failedTests = []

    def javaTests = testNames.findAll { it.contains('.java') }
    def pythonTests = testNames.findAll { it.contains('test_') }

    if (javaTests) {
        try {
            sh "mvn test -Dtest='${javaTests.join(',')}'"
        } catch (Exception e) {
            failedTests.addAll(javaTests)
        }
    }

    if (pythonTests) {
        try {
            sh "pytest ${pythonTests.join(' ')} -v"
        } catch (Exception e) {
            failedTests.addAll(pythonTests)
        }
    }

    return [failedTests: failedTests]
}

// Utility methods
def calculateFlakinessScore(testHistory) {
    def totalRuns = testHistory.totalRuns
    def flakyRuns = testHistory.flakyRuns

    if (totalRuns == 0) return 0.0

    return flakyRuns / totalRuns.toDouble()
}

def parseTestResults(reportDir) {
    def failedTests = []

    def files = findFiles(glob: "${reportDir}/**/*.xml")
    files.each { file ->
        def xml = readXML file: file.path
        xml.'testsuite'.'testcase'.each { testcase ->
            if (testcase.failure || testcase.error) {
                failedTests << testcase.@name
            }
        }
    }

    return failedTests
}

