            script {
                // Automatic rollback on failure
                sh "kubectl patch service app-service -p '{"spec":{"selector":{"color":"${CURRENT_COLOR}"}}}'"
                slackSend channel: '#alerts', message: "🚨 Deployment failed - rolled back to ${CURRENT_COLOR}"
            }
        }
    }
}

// Intelligent Retry and Reporting Pipeline
pipeline {
    agent any
    options {
        retry(2)  // Retry entire pipeline on infrastructure failures
        timeout(time: 2, unit: 'HOURS')
    }

    stages {
        stage('Flaky Test Handling') {
            steps {
                script {
                    def testsPassed = false
                    def attempt = 0
                    def maxAttempts = 3

                    while (!testsPassed && attempt < maxAttempts) {
                        attempt++
                        try {
                            sh 'npm run test:flaky'
                            testsPassed = true
                            echo "Flaky tests passed on attempt ${attempt}"
                        } catch (Exception e) {
                            echo "Flaky tests failed on attempt ${attempt}"
                            if (attempt == maxAttempts) {
                                // On final attempt, run with extra logging
                                sh 'npm run test:flaky -- --verbose --retries=3'
                            }
                        }
                    }
                }
            }
        }

        stage('Smart Failure Analysis') {
            steps {
                script {
                    try {
                        sh 'npm run test:all'
                    } catch (Exception e) {
                        // Analyze test results
                        def testResults = readJSON file: 'test-results.json'
                        def failurePatterns = analyzeFailures(testResults)

                        if (failurePatterns.environmental) {
                            echo "Environmental failure detected - triggering infrastructure reset"
                            build job: 'reset-test-environment', wait: false
                        }

                        if (failurePatterns.regression) {
                            slackSend channel: '#team-regressions', 
                                     message: "🚨 Regression detected in ${env.JOB_NAME}: ${failurePatterns.regressionDetails}"
                        }

                        // Fail the stage with contextual message
                        error("Test failures: ${failurePatterns.summary}")
                    }
                }
            }
        }
    }

    post {
        always {
            // Comprehensive reporting
            publishHTML([
                target: [
                    reportDir: 'coverage',
                    reportFiles: 'index.html',
                    reportName: 'Coverage Report'
                ]
            ])

            junit 'test-results/**/*.xml'

            // Custom quality gate analysis
            script {
                def qualityReport = generateQualityReport()
                emailext (
                    subject: "${env.JOB_NAME} - Build #${env.BUILD_NUMBER} - ${currentBuild.currentResult}",
                    body: """
                    Build Result: ${currentBuild.currentResult}
                    Quality Score: ${qualityReport.score}/100
                    Test Coverage: ${qualityReport.coverage}%
                    Security Issues: ${qualityReport.securityIssues}
                    Performance Impact: ${qualityReport.performanceImpact}

                    Detailed Report: ${env.BUILD_URL}
                    """,
                    to: 'team@company.com'
                )
            }
        }

        success {
            script {
                // Auto-promote if all quality gates pass
                if (qualityReport.score >= 90) {
                    build job: 'promote-to-staging', wait: false
                }
            }
        }

        unstable {
            slackSend channel: '#test-flakiness', 
                     message: "⚠️ ${env.JOB_NAME} has flaky tests. Build: ${env.BUILD_URL}"
        }

        failure {
            script {
                // Smart failure categorization
                def failureReason = currentBuild.getBuildCauses()[0].toString()
                if (failureReason.contains('Timeout')) {
                    slackSend channel: '#infrastructure-alerts',
                             message: "⏰ Pipeline timeout in ${env.JOB_NAME}"
                } else {
                    slackSend channel: '#build-failures',
                             message: "❌ Build failed: ${env.BUILD_URL}"
                }
            }
        }
    }
}

// Helper function for failure analysis
def analyzeFailures(testResults) {
    def patterns = [
        environmental: false,
        regression: false,
        summary: '',
        regressionDetails: ''
    ]

    testResults.testSuites.each { suite ->
        suite.testCases.each { testCase ->
            if (testCase.failed) {
                if (testCase.error.contains('Connection refused') || 
                    testCase.error.contains('Timeout')) {
                    patterns.environmental = true
                    patterns.summary += 'Environmental failures detected. '
                }

                if (testCase.wasPassingInPreviousBuild) {
                    patterns.regression = true
                    patterns.regressionDetails += "${testCase.name}, "
                }
            }
        }
    }

    return patterns
}

