    def update_failure_thread(self, thread_ts, additional_info):
        """Update failure thread with additional information"""
        message = {
            "channel": self.channel,
            "thread_ts": thread_ts,
            "text": "Additional failure information",
            "blocks": [
                {
                    "type": "section",
                    "text": {
                        "type": "mrkdwn",
                        "text": f"*Additional Analysis:*\n{additional_info}"
                    }
                }
            ]
        }

        self._send_message(message)

    def _send_message(self, message):
        """Send message to Slack"""
        response = requests.post(
            self.webhook_url,
            data=json.dumps(message),
            headers={'Content-Type': 'application/json'}
        )

        if response.status_code != 200:
            raise ValueError(f"Request to Slack returned error {response.status_code}: {response.text}")

        return response

