// Webhook notification methods
def sendWebhookNotifications() {
    def payload = buildWebhookPayload()

    // Send to multiple webhook endpoints with retry
    def webhooks = [
        [url: env.DASHBOARD_WEBHOOK, type: 'dashboard'],
        [url: env.MONITORING_WEBHOOK, type: 'monitoring'],
        [url: env.ALERTING_WEBHOOK, type: 'alerting']
    ]

    webhooks.each { webhook ->
        retry(3) {
            sendWebhook(webhook.url, payload, webhook.type)
        }
    }
}

def buildWebhookPayload() {
    def testSummary = generateTestSummary()
    def buildInfo = getBuildInfo()

    return [
        event: 'build_completed',
        timestamp: new Date().time,
        build: [
            job_name: env.JOB_NAME,
            build_number: env.BUILD_NUMBER.toInteger(),
            result: currentBuild.currentResult,
            duration: currentBuild.duration,
            url: env.BUILD_URL,
            triggered_by: env.BUILD_USER
        ],
        source: [
            branch: env.GIT_BRANCH,
            commit: env.GIT_COMMIT,
            repository: env.GIT_URL
        ],
        tests: [
            total: testSummary.total,
            passed: testSummary.passed,
            failed: testSummary.failed,
            skipped: testSummary.skipped,
            pass_rate: testSummary.passRate,
            duration: testSummary.duration
        ],
        environment: [
            name: params.ENVIRONMENT,
            url: env.APP_BASE_URL
        ],
        quality_gates: evaluateQualityGates(),
        metadata: [
            pipeline_version: '1.0',
            notification_id: "${env.JOB_NAME}-${env.BUILD_NUMBER}"
        ]
    ]
}

def sendWebhook(String webhookUrl, Map payload, String type) {
    def customizedPayload = customizePayloadForType(payload, type)

    sh """
    curl -X POST \
         -H 'Content-Type: application/json' \
         -H 'User-Agent: Jenkins-CI' \
         -H 'X-Jenkins-Build: ${env.BUILD_NUMBER}' \
         -d '${writeJSON returnText: true, json: customizedPayload}' \
         --connect-timeout 10 \
         --max-time 30 \
         '${webhookUrl}'
    """

    echo "Webhook sent to ${type} endpoint"
}

def customizePayloadForType(Map payload, String type) {
    def customized = payload.clone()

    switch(type) {
        case 'dashboard':
            customized.metrics = generateDashboardMetrics()
            customized.trends = generateTrendData()
            break
        case 'monitoring':
            customized.alert_level = determineAlertLevel()
            customized.metrics = generateMonitoringMetrics()
            break
        case 'alerting':
            customized.priority = determinePriority()
            customized.actions = generateAlertActions()
            break
    }

    return customized
}

