// Quality gate implementation
def runQualityGates() {
    def qualityResults = [:]

    // Test Coverage Gate
    qualityResults.coverage = evaluateTestCoverage()
    if (qualityResults.coverage.passed) {
        echo "✅ Test coverage gate passed: ${qualityResults.coverage.value}%"
    } else {
        echo "❌ Test coverage gate failed: ${qualityResults.coverage.value}% (threshold: ${qualityResults.coverage.threshold}%)"
        currentBuild.result = 'UNSTABLE'
    }

    // Test Success Rate Gate
    qualityResults.successRate = evaluateTestSuccessRate()
    if (qualityResults.successRate.passed) {
        echo "✅ Test success rate gate passed: ${qualityResults.successRate.value}%"
    } else {
        echo "❌ Test success rate gate failed: ${qualityResults.successRate.value}% (threshold: ${env.QUALITY_GATE_THRESHOLD}%)"
        currentBuild.result = 'FAILURE'
    }

    // Performance Gate
    qualityResults.performance = evaluatePerformance()
    if (qualityResults.performance.passed) {
        echo "✅ Performance gate passed: ${qualityResults.performance.value}ms"
    } else {
        echo "❌ Performance gate failed: ${qualityResults.performance.value}ms (threshold: ${env.PERFORMANCE_THRESHOLD}ms)"
        currentBuild.result = 'UNSTABLE'
    }

    // Security Gate
    qualityResults.security = evaluateSecurity()
    if (qualityResults.security.passed) {
        echo "✅ Security gate passed: ${qualityResults.security.value} vulnerabilities"
    } else {
        echo "❌ Security gate failed: ${qualityResults.security.value} vulnerabilities (threshold: ${env.SECURITY_THRESHOLD})"
        currentBuild.result = 'FAILURE'
    }

    // Code Quality Gate
    qualityResults.codeQuality = evaluateCodeQuality()
    if (qualityResults.codeQuality.passed) {
        echo "✅ Code quality gate passed: ${qualityResults.codeQuality.value} issues"
    } else {
        echo "❌ Code quality gate failed: ${qualityResults.codeQuality.value} issues"
        currentBuild.result = 'UNSTABLE'
    }

    return qualityResults
}

// Failure analysis methods
def performFailureAnalysis() {
    def analysis = [:]

    // Determine failure type
    analysis.failureType = determineFailureType()
    analysis.failedStage = getFailedStage()
    analysis.errorMessage = getErrorMessage()

    // Root cause analysis
    analysis.rootCause = analyzeRootCause()
    analysis.impactAssessment = assessImpact()
    analysis.recommendation = generateRecommendation()

    // Failure categorization
    analysis.category = categorizeFailure()
    analysis.severity = determineSeverity()
    analysis.escalationRequired = isEscalationRequired(analysis)

    // Historical analysis
    analysis.historicalPattern = checkHistoricalPatterns()
    analysis.similarFailures = findSimilarFailures()

    return analysis
}

def determineFailureType() {
    def failureType = 'UNKNOWN'

    // Analyze console output and test results
    def consoleOutput = currentBuild.rawBuild.getLog(100)

    if (consoleOutput.contains('Compilation failed')) {
        failureType = 'COMPILATION_ERROR'
    } else if (consoleOutput.contains('Test FAILED')) {
        failureType = 'TEST_FAILURE'
    } else if (consoleOutput.contains('Timeout')) {
        failureType = 'TIMEOUT'
    } else if (consoleOutput.contains('Connection refused') || consoleOutput.contains('Network is unreachable')) {
        failureType = 'NETWORK_ERROR'
    } else if (consoleOutput.contains('OutOfMemoryError') || consoleOutput.contains('Java heap space')) {
        failureType = 'RESOURCE_EXHAUSTION'
    } else if (consoleOutput.contains('Permission denied')) {
        failureType = 'PERMISSION_ERROR'
    }

    return failureType
}

def analyzeRootCause() {
    def rootCause = 'UNKNOWN'
    def failureType = determineFailureType()

    switch(failureType) {
        case 'COMPILATION_ERROR':
            rootCause = 'Code syntax error or dependency issue'
            break
        case 'TEST_FAILURE':
            def testAnalysis = analyzeTestFailures()
            rootCause = testAnalysis.commonCause ?: 'Functional regression'
            break
        case 'TIMEOUT':
            rootCause = 'Slow tests or resource constraints'
            break
        case 'NETWORK_ERROR':
            rootCause = 'Infrastructure or service availability issue'
            break
        case 'RESOURCE_EXHAUSTION':
            rootCause = 'Insufficient memory or CPU allocation'
            break
        case 'PERMISSION_ERROR':
            rootCause = 'Configuration or security policy issue'
            break
    }

    return rootCause
}

def evaluateQualityGates(Map failureAnalysis) {
    def qualityGates = [:]

    // Test Stability Gate
    qualityGates.testStability = evaluateTestStability()

    // Flaky Test Gate
    qualityGates.flakyTests = evaluateFlakyTests()

    // Performance Regression Gate
    qualityGates.performanceRegression = evaluatePerformanceRegression()

    // Security Compliance Gate
    qualityGates.securityCompliance = evaluateSecurityCompliance()

    // Deployment Readiness Gate
    qualityGates.deploymentReadiness = evaluateDeploymentReadiness(failureAnalysis)

    return qualityGates
}

def generateQualityReport() {
    def report = [
        timestamp: new Date().format('yyyy-MM-dd HH:mm:ss'),
        build: [
            job: env.JOB_NAME,
            number: env.BUILD_NUMBER,
            result: currentBuild.currentResult,
            duration: currentBuild.durationString
        ],
        qualityGates: runQualityGates(),
        failureAnalysis: env.FAILURE_ANALYSIS ?: [:],
        recommendations: generateQualityRecommendations(),
        metrics: collectQualityMetrics()
    ]

    writeJSON file: 'quality-report.json', json: report
    archiveArtifacts 'quality-report.json'

    return report
}

pipeline {
    agent any
    environment {
        ESCALATION_LEVEL = 'NONE'
        INCIDENT_SEVERITY = 'LOW'
        ON_CALL_TEAM = 'platform-engineering@company.com'
        MANAGEMENT_TEAM = 'engineering-managers@company.com'
    }
    stages {
        stage('Build and Test') {
            steps {
                script {
                    sh 'mvn clean test'
                }
            }
        }
    }
    post {
        failure {
            script {
                // Analyze failure and determine escalation level
                def escalation = determineEscalationPolicy()
                env.ESCALATION_LEVEL = escalation.level
                env.INCIDENT_SEVERITY = escalation.severity

                // Execute escalation policy
                executeEscalationPolicy(escalation)
            }
        }
    }
}

// Escalation policy implementation
def determineEscalationPolicy() {
    def escalation = [
        level: 'NONE',
        severity: 'LOW',
        actions: [],
        teams: []
    ]

    def failureAnalysis = performFailureAnalysis()
    def impact = assessFailureImpact(failureAnalysis)

    // Determine escalation level based on impact and failure type
    if (impact.critical) {
        escalation.level = 'CRITICAL'
        escalation.severity = 'SEV1'
        escalation.teams = [env.ON_CALL_TEAM, env.MANAGEMENT_TEAM, 'cto@company.com']
        escalation.actions = ['create_incident', 'page_on_call', 'notify_management', 'create_postmortem']
    } else if (impact.high) {
        escalation.level = 'HIGH'
        escalation.severity = 'SEV2'
        escalation.teams = [env.ON_CALL_TEAM, 'tech-leads@company.com']
        escalation.actions = ['create_incident', 'notify_team', 'schedule_review']
    } else if (impact.medium) {
        escalation.level = 'MEDIUM'
        escalation.severity = 'SEV3'
        escalation.teams = ['dev-team@company.com']
        escalation.actions = ['create_ticket', 'notify_team']
    } else {
        escalation.level = 'LOW'
        escalation.severity = 'SEV4'
        escalation.teams = ['qa-team@company.com']
        escalation.actions = ['log_issue']
    }

    return escalation
}

def executeEscalationPolicy(Map escalation) {
    echo "Executing escalation policy: Level ${escalation.level}, Severity ${escalation.severity}"

    escalation.actions.each { action ->
        switch(action) {
            case 'create_incident':
                createIncident(escalation)
                break
            case 'page_on_call':
                pageOnCallTeam(escalation)
                break
            case 'notify_management':
                notifyManagement(escalation)
                break
            case 'create_postmortem':
                schedulePostmortem(escalation)
                break
            case 'notify_team':
                notifyTeam(escalation)
                break
            case 'create_ticket':
                createTicket(escalation)
                break
            case 'log_issue':
                logIssue(escalation)
                break
        }
    }
}

def createIncident(Map escalation) {
    def incidentData = [
        title: "Build Failure - ${env.JOB_NAME} #${env.BUILD_NUMBER}",
        description: "Critical build failure requiring immediate attention",
        severity: escalation.severity,
        priority: getIncidentPriority(escalation.level),
        teams: escalation.teams,
        build_info: [
            job: env.JOB_NAME,
            build_number: env.BUILD_NUMBER,
            url: env.BUILD_URL,
            failed_stage: getFailedStage(),
            error_message: getErrorMessage()
        ],
        analysis: env.FAILURE_ANALYSIS
    ]

    // Create incident in incident management system
    sh """
    curl -X POST \
         -H 'Content-Type: application/json' \
         -H 'Authorization: Bearer ${env.INCIDENT_API_TOKEN}' \
         -d '${writeJSON returnText: true, json: incidentData}' \
         '${env.INCIDENT_MANAGEMENT_URL}/api/incidents'
    """

    echo "Incident created with severity: ${escalation.severity}"
}

def pageOnCallTeam(Map escalation) {
    def pagingMessage = """
    🚨 CRITICAL BUILD FAILURE 🚨

    Job: ${env.JOB_NAME}
    Build: #${env.BUILD_NUMBER}
    Severity: ${escalation.severity}
    Failed Stage: ${getFailedStage()}

    Immediate attention required. Please investigate:
    ${env.BUILD_URL}
    """

    // Send page via PagerDuty, OpsGenie, etc.
    sh """
    curl -X POST \
         -H 'Content-Type: application/json' \
         -d '{
           "message": "${pagingMessage}",
           "teams": ["platform-engineering"],
           "priority": "critical"
         }' \
         '${env.PAGING_SERVICE_URL}'
    """

    echo "On-call team paged for critical failure"
}

def notifyManagement(Map escalation) {
    def managementMessage = """
    Management Alert: Critical Build Failure

    A critical build failure requires management attention:

    • Job: ${env.JOB_NAME}
    • Build: #${env.BUILD_NUMBER}
    • Severity: ${escalation.severity}
    • Impact: ${assessBusinessImpact()}
    • Estimated Resolution Time: ${estimateResolutionTime()}

    Incident has been created and on-call team notified.
    """

    emailext(
        to: env.MANAGEMENT_TEAM,
        subject: "🚨 MANAGEMENT ALERT: Critical Build Failure - ${env.JOB_NAME} #${env.BUILD_NUMBER}",
        body: managementMessage,
        mimeType: 'text/html'
    )

    // Also send to Slack management channel
    slackSend(
        channel: '#engineering-management',
        message: managementMessage,
        color: 'danger'
    )
}

def assessFailureImpact(Map failureAnalysis) {
    def impact = [
        critical: false,
        high: false,
        medium: false,
        low: true
    ]

    // Critical impact conditions
    if (failureAnalysis.failureType in ['COMPILATION_ERROR', 'SECURITY_ISSUE']) {
        impact.critical = true
        impact.high = false
        impact.medium = false
        impact.low = false
    }

    // High impact conditions
    if (failureAnalysis.failureType == 'TEST_FAILURE' && 
        failureAnalysis.failedTestsCount > 10) {
        impact.high = true
        impact.medium = false
        impact.low = false
    }

    // Medium impact conditions
    if (failureAnalysis.failureType == 'PERFORMANCE_DEGRADATION') {
        impact.medium = true
        impact.low = false
    }

    return impact
}

def getIncidentPriority(String escalationLevel) {
    def priorities = [
        'CRITICAL': 'P0',
        'HIGH': 'P1', 
        'MEDIUM': 'P2',
        'LOW': 'P3'
    ]

    return priorities[escalationLevel] ?: 'P3'
}

def schedulePostmortem(Map escalation) {
    if (escalation.level in ['CRITICAL', 'HIGH']) {
        def postmortemData = [
            title: "Postmortem: ${env.JOB_NAME} Build #${env.BUILD_NUMBER} Failure",
            incident_severity: escalation.severity,
            scheduled_time: new Date() + 1, // Schedule for tomorrow
            attendees: escalation.teams,
            build_info: [
                job: env.JOB_NAME,
                build_number: env.BUILD_NUMBER,
                failure_analysis: env.FAILURE_ANALYSIS
            ]
        ]

        // Create postmortem event
        sh """
        curl -X POST \
             -H 'Content-Type: application/json' \
             -d '${writeJSON returnText: true, json: postmortemData}' \
             '${env.POSTMORTEM_SERVICE_URL}/api/postmortems'
        """

        echo "Postmortem scheduled for ${escalation.severity} incident"
    }
}

#!/usr/bin/env python3
# escalation_manager.py - Advanced escalation management with intelligent routing

import json
import requests
from datetime import datetime, timedelta
from enum import Enum
from typing import Dict, List, Optional

class SeverityLevel(Enum):
    SEV1 = "Critical"
    SEV2 = "High" 
    SEV3 = "Medium"
    SEV4 = "Low"

class EscalationLevel(Enum):
    CRITICAL = "CRITICAL"
    HIGH = "HIGH"
    MEDIUM = "MEDIUM"
    LOW = "LOW"

class EscalationPolicy:
    def __init__(self, name: str, conditions: Dict, actions: List[str], teams: List[str]):
        self.name = name
        self.conditions = conditions
        self.actions = actions
        self.teams = teams

    def matches(self, failure_data: Dict) -> bool:
        """Check if this policy matches the failure conditions"""
        for condition, value in self.conditions.items():
            if not self._evaluate_condition(condition, value, failure_data):
                return False
        return True

    def _evaluate_condition(self, condition: str, expected_value, failure_data: Dict) -> bool:
        """Evaluate a single condition"""
        actual_value = failure_data.get(condition)

        if condition == "failure_type":
            return actual_value == expected_value
        elif condition == "failed_tests_count":
            return actual_value >= expected_value
        elif condition == "impact_score":
            return actual_value >= expected_value
        elif condition == "time_since_last_failure":
            return self._check_time_condition(actual_value, expected_value)

        return False

    def _check_time_condition(self, actual_time: str, expected_hours: int) -> bool:
        """Check if failure occurred within specified time window"""
        if not actual_time:
            return False

        failure_time = datetime.fromisoformat(actual_time)
        time_threshold = datetime.now() - timedelta(hours=expected_hours)

        return failure_time >= time_threshold

class EscalationManager:
    def __init__(self):
        self.policies = self._load_escalation_policies()
        self.incident_history = []

    def _load_escalation_policies(self) -> List[EscalationPolicy]:
        """Load escalation policies from configuration"""
        return [
            # Critical policy - SEV1
            EscalationPolicy(
                name="CRITICAL_FAILURE",
                conditions={
                    "failure_type": "COMPILATION_ERROR",
                    "impact_score": 90
                },
                actions=["create_incident", "page_on_call", "notify_management", "schedule_postmortem"],
                teams=["platform-engineering", "engineering-management", "cto"]
            ),

            # High policy - SEV2
            EscalationPolicy(
                name="HIGH_IMPACT_FAILURE", 
                conditions={
                    "failure_type": "TEST_FAILURE",
                    "failed_tests_count": 10,
                    "impact_score": 70
                },
                actions=["create_incident", "notify_team_leads", "schedule_review"],
                teams=["platform-engineering", "tech-leads"]
            ),

            # Medium policy - SEV3
            EscalationPolicy(
                name="MEDIUM_IMPACT_FAILURE",
                conditions={
                    "failure_type": "PERFORMANCE_DEGRADATION", 
                    "impact_score": 50
                },
                actions=["create_ticket", "notify_team"],
                teams=["development-team"]
            ),

            # Low policy - SEV4
            EscalationPolicy(
                name="LOW_IMPACT_FAILURE",
                conditions={
                    "impact_score": 20
                },
                actions=["log_issue"],
                teams=["qa-team"]
            )
        ]

    def determine_escalation(self, failure_data: Dict) -> Dict:
        """Determine appropriate escalation policy for failure"""
        # Calculate impact score
        impact_score = self._calculate_impact_score(failure_data)
        failure_data["impact_score"] = impact_score

        # Find matching policy
        matching_policy = None
        for policy in self.policies:
            if policy.matches(failure_data):
                matching_policy = policy
                break

        if not matching_policy:
            # Default to low impact
            matching_policy = self.policies[-1]

        return {
            "policy_name": matching_policy.name,
            "severity": self._get_severity_level(matching_policy.name),
            "escalation_level": self._get_escalation_level(matching_policy.name),
            "actions": matching_policy.actions,
            "teams": matching_policy.teams,
            "impact_score": impact_score,
            "timestamp": datetime.now().isoformat()
        }

    def execute_escalation(self, escalation: Dict, failure_data: Dict):
        """Execute escalation actions"""
        print(f"Executing escalation: {escalation['policy_name']}")
        print(f"Severity: {escalation['severity']}")
        print(f"Teams: {', '.join(escalation['teams'])}")

        for action in escalation['actions']:
            self._execute_action(action, escalation, failure_data)

        # Log escalation
        self._log_escalation(escalation, failure_data)

    def _calculate_impact_score(self, failure_data: Dict) -> float:
        """Calculate impact score (0-100) based on failure characteristics"""
        score = 0.0

        # Factor 1: Failure type
        failure_type_scores = {
            "COMPILATION_ERROR": 90,
            "SECURITY_ISSUE": 95,
            "TEST_FAILURE": 60,
            "PERFORMANCE_DEGRADATION": 50,
            "TIMEOUT": 40,
            "NETWORK_ERROR": 30
        }
        score += failure_type_scores.get(failure_data.get("failure_type"), 20)

        # Factor 2: Failed tests count
        failed_tests = failure_data.get("failed_tests_count", 0)
        score += min(30, failed_tests * 2)  # Max 30 points for test failures

        # Factor 3: Recent failure frequency
        recent_failures = self._count_recent_failures(hours=24)
        score += min(20, recent_failures * 5)  # Max 20 points for frequency

        return min(100, score)

    def _execute_action(self, action: str, escalation: Dict, failure_data: Dict):
        """Execute a specific escalation action"""
        action_handlers = {
            "create_incident": self._create_incident,
            "page_on_call": self._page_on_call,
            "notify_management": self._notify_management,
            "schedule_postmortem": self._schedule_postmortem,
            "notify_team_leads": self._notify_team_leads,
            "schedule_review": self._schedule_review,
            "create_ticket": self._create_ticket,
            "notify_team": self._notify_team,
            "log_issue": self._log_issue
        }

        handler = action_handlers.get(action)
        if handler:
            handler(escalation, failure_data)

    def _create_incident(self, escalation: Dict, failure_data: Dict):
        """Create incident in incident management system"""
        incident_data = {
            "title": f"Build Failure - {failure_data.get('job_name')} #{failure_data.get('build_number')}",
            "description": failure_data.get('error_message', 'Build failure occurred'),
            "severity": escalation['severity'].value,
            "priority": self._get_incident_priority(escalation['escalation_level']),
            "teams": escalation['teams'],
            "build_info": failure_data,
            "escalation_policy": escalation['policy_name']
        }

        # Send to incident management system
        try:
            response = requests.post(
                "https://incidents.company.com/api/incidents",
                json=incident_data,
                headers={"Authorization": f"Bearer {os.getenv('INCIDENT_API_TOKEN')}"},
                timeout=30
            )

            if response.status_code == 201:
                print(f"Incident created: {response.json().get('id')}")
            else:
                print(f"Failed to create incident: {response.status_code}")

        except Exception as e:
            print(f"Error creating incident: {e}")

    def _page_on_call(self, escalation: Dict, failure_data: Dict):
        """Page on-call team"""
        message = f"""
        🚨 {escalation['severity'].value} INCIDENT 🚨

        Build Failure: {failure_data.get('job_name')} #{failure_data.get('build_number')}
        Impact Score: {escalation['impact_score']}

        Immediate attention required.
        """

        # Send to paging service (PagerDuty, OpsGenie, etc.)
        paging_data = {
            "message": message,
            "teams": ["platform-engineering"],
            "priority": "critical" if escalation['severity'] == SeverityLevel.SEV1 else "high"
        }

        try:
            requests.post(
                "https://paging.company.com/api/alerts",
                json=paging_data,
                timeout=10
            )
            print("On-call team paged successfully")
        except Exception as e:
            print(f"Error paging on-call team: {e}")

    def _get_severity_level(self, policy_name: str) -> SeverityLevel:
        """Map policy name to severity level"""
        severity_map = {
            "CRITICAL_FAILURE": SeverityLevel.SEV1,
            "HIGH_IMPACT_FAILURE": SeverityLevel.SEV2,
            "MEDIUM_IMPACT_FAILURE": SeverityLevel.SEV3,
            "LOW_IMPACT_FAILURE": SeverityLevel.SEV4
        }
        return severity_map.get(policy_name, SeverityLevel.SEV4)

    def _get_escalation_level(self, policy_name: str) -> EscalationLevel:
        """Map policy name to escalation level"""
        escalation_map = {
            "CRITICAL_FAILURE": EscalationLevel.CRITICAL,
            "HIGH_IMPACT_FAILURE": EscalationLevel.HIGH,
            "MEDIUM_IMPACT_FAILURE": EscalationLevel.MEDIUM,
            "LOW_IMPACT_FAILURE": EscalationLevel.LOW
        }
        return escalation_map.get(policy_name, EscalationLevel.LOW)

    def _get_incident_priority(self, escalation_level: EscalationLevel) -> str:
        """Get incident priority based on escalation level"""
        priority_map = {
            EscalationLevel.CRITICAL: "P0",
            EscalationLevel.HIGH: "P1",
            EscalationLevel.MEDIUM: "P2", 
            EscalationLevel.LOW: "P3"
        }
        return priority_map.get(escalation_level, "P3")

    def _count_recent_failures(self, hours: int) -> int:
        """Count failures in recent time period"""
        cutoff_time = datetime.now() - timedelta(hours=hours)

        recent_failures = [
            incident for incident in self.incident_history
            if datetime.fromisoformat(incident['timestamp']) >= cutoff_time
            and incident['severity'] in [SeverityLevel.SEV1, SeverityLevel.SEV2]
        ]

        return len(recent_failures)

    def _log_escalation(self, escalation: Dict, failure_data: Dict):
        """Log escalation for historical tracking"""
        log_entry = {
            "timestamp": datetime.now().isoformat(),
            "escalation": escalation,
            "failure_data": failure_data
        }

        self.incident_history.append(log_entry)

# Usage example
if __name__ == "__main__":
    manager = EscalationManager()

    # Example failure data
    failure_data = {
        "job_name": "api-service",
        "build_number": 123,
        "failure_type": "COMPILATION_ERROR",
        "error_message": "Compilation failed: missing dependency",
        "failed_tests_count": 0,
        "timestamp": datetime.now().isoformat()
    }

    # Determine escalation
    escalation = manager.determine_escalation(failure_data)

    # Execute escalation
    manager.execute_escalation(escalation, failure_data)

    print(f"Escalation completed: {escalation['policy_name']}")
    print(f"Impact score: {escalation['impact_score']}")

