// Credential management methods
def validateCredentials() {
    def requiredCredentials = [
        'test-db-credentials',
        'test-api-key',
        'oauth-token'
    ]

    requiredCredentials.each { credId ->
        try {
            withCredentials([string(credentialsId: credId, variable: 'TEST_CRED')]) {
                echo "Credential ${credId} is accessible"
            }
        } catch (Exception e) {
            error "Missing or invalid credential: ${credId}"
        }
    }
}

def shouldRotateCredentials() {
    // Check if credentials need rotation based on age
    def credentialAge = getCredentialAge('test-db-credentials')
    return credentialAge > 30 // Rotate if older than 30 days
}

def rotateCredentials() {
    echo "Rotating credentials..."

    // Generate new credentials
    def newDbPassword = generateSecurePassword()
    def newApiKey = generateApiKey()

    // Update in secure storage
    updateCredentialInVault('test-db-password', newDbPassword)
    updateCredentialInVault('test-api-key', newApiKey)

    // Update in Jenkins credentials store
    updateJenkinsCredential('test-db-credentials', newDbPassword)
    updateJenkinsCredential('test-api-key', newApiKey)

    echo "Credentials rotated successfully"
}

def maskSensitiveData() {
    // Add patterns to mask in build logs
    def sensitivePatterns = [
        /password.*=.*[^\s]+/,
        /api_key.*=.*[^\s]+/,
        /token.*=.*[^\s]+/,
        /secret.*=.*[^\s]+/,
        /[A-Za-z0-9+/]{40}/, // Base64-like patterns
        /[0-9a-f]{32}/ // Hex patterns (MD5, SHA hashes)
    ]

    sensitivePatterns.each { pattern ->
        manager.addRegexBadge(pattern, 'SENSITIVE_DATA')
    }
}

#!/usr/bin/env python3
# credential_manager.py - Advanced credential management and rotation

import os
import json
import secrets
import string
import hashlib
from datetime import datetime, timedelta
from typing import Dict, Optional
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
import base64

class SecureCredentialManager:
    def __init__(self, vault_url: str, namespace: str):
        self.vault_url = vault_url
        self.namespace = namespace
        self.encryption_key = self._load_encryption_key()

    def _load_encryption_key(self) -> bytes:
        """Load encryption key from secure location"""
        key_path = os.getenv('ENCRYPTION_KEY_PATH', '/etc/secrets/encryption.key')

        try:
            with open(key_path, 'rb') as key_file:
                return key_file.read()
        except FileNotFoundError:
            # Generate new key for development
            return Fernet.generate_key()

    def generate_secure_password(self, length: int = 32) -> str:
        """Generate cryptographically secure password"""
        alphabet = string.ascii_letters + string.digits + "!@#$%^&*"
        return ''.join(secrets.choice(alphabet) for _ in range(length))

    def generate_api_key(self, prefix: str = "sk_test_") -> str:
        """Generate secure API key"""
        random_bytes = secrets.token_bytes(32)
        return prefix + base64.urlsafe_b64encode(random_bytes).decode('utf-8').rstrip('=')

    def encrypt_value(self, value: str) -> str:
        """Encrypt sensitive value"""
        fernet = Fernet(self.encryption_key)
        encrypted = fernet.encrypt(value.encode('utf-8'))
        return base64.urlsafe_b64encode(encrypted).decode('utf-8')

    def decrypt_value(self, encrypted_value: str) -> str:
        """Decrypt sensitive value"""
        fernet = Fernet(self.encryption_key)
        encrypted_bytes = base64.urlsafe_b64decode(encrypted_value)
        return fernet.decrypt(encrypted_bytes).decode('utf-8')

    def store_credential(self, credential_name: str, credential_value: str, 
                        metadata: Dict = None) -> bool:
        """Store credential in secure storage"""
        try:
            # Encrypt the credential
            encrypted_value = self.encrypt_value(credential_value)

            # Prepare credential data
            credential_data = {
                'value': encrypted_value,
                'created_at': datetime.now().isoformat(),
                'version': 1,
                'metadata': metadata or {}
            }

            # Store in secure backend (Vault, AWS Secrets Manager, etc.)
            return self._store_in_backend(credential_name, credential_data)

        except Exception as e:
            print(f"Error storing credential {credential_name}: {e}")
            return False

    def retrieve_credential(self, credential_name: str, version: int = None) -> Optional[str]:
        """Retrieve credential from secure storage"""
        try:
            # Retrieve from secure backend
            credential_data = self._retrieve_from_backend(credential_name, version)

            if not credential_data:
                return None

            # Decrypt the value
            decrypted_value = self.decrypt_value(credential_data['value'])

            # Audit the access
            self._audit_access(credential_name, 'retrieve')

            return decrypted_value

        except Exception as e:
            print(f"Error retrieving credential {credential_name}: {e}")
            return None

    def rotate_credential(self, credential_name: str, new_value: str = None) -> bool:
        """Rotate credential with new value"""
        try:
            # Generate new value if not provided
            if not new_value:
                new_value = self.generate_secure_password()

            # Retrieve current credential metadata
            current_data = self._retrieve_from_backend(credential_name)

            if not current_data:
                print(f"Credential {credential_name} not found")
                return False

            # Store new version
            new_version = current_data.get('version', 0) + 1

            new_credential_data = {
                'value': self.encrypt_value(new_value),
                'created_at': datetime.now().isoformat(),
                'version': new_version,
                'metadata': current_data.get('metadata', {}),
                'previous_version': current_data['version']
            }

            # Update in backend
            success = self._store_in_backend(credential_name, new_credential_data)

            if success:
                # Archive old version
                self._archive_credential(credential_name, current_data)

                # Notify about rotation
                self._notify_rotation(credential_name)

                print(f"Credential {credential_name} rotated successfully to version {new_version}")

            return success

        except Exception as e:
            print(f"Error rotating credential {credential_name}: {e}")
            return False

