import json
import time
import boto3
from concurrent.futures import ThreadPoolExecutor, as_completed

class ServerlessPerformanceTester:
    def __init__(self, lambda_client, function_name):
        self.lambda_client = lambda_client
        self.function_name = function_name
        self.results = []

    def execute_test(self, payload, test_id):
        """Execute a single test invocation"""
        start_time = time.time()

        try:
            response = self.lambda_client.invoke(
                FunctionName=self.function_name,
                InvocationType='RequestResponse',
                Payload=json.dumps(payload)
            )

            end_time = time.time()
            duration = end_time - start_time

            # Parse response
            result = json.loads(response['Payload'].read())

            return {
                'test_id': test_id,
                'status_code': response['StatusCode'],
                'duration': duration,
                'result': result,
                'success': response['StatusCode'] == 200
            }

        except Exception as e:
            return {
                'test_id': test_id,
                'error': str(e),
                'success': False
            }

    def run_concurrent_tests(self, payload_template, concurrent_users, total_requests):
        """Run concurrent tests using thread pool"""
        with ThreadPoolExecutor(max_workers=concurrent_users) as executor:
            # Submit all test requests
            future_to_test = {
                executor.submit(self.execute_test, payload_template, i): i
                for i in range(total_requests)
            }

            # Collect results as they complete
            for future in as_completed(future_to_test):
                test_id = future_to_test[future]
                try:
                    result = future.result()
                    self.results.append(result)
                except Exception as exc:
                    self.results.append({
                        'test_id': test_id,
                        'error': str(exc),
                        'success': False
                    })

    def generate_report(self):
        """Generate performance test report"""
        successful_tests = [r for r in self.results if r['success']]
        failed_tests = [r for r in self.results if not r['success']]

        if successful_tests:
            durations = [r['duration'] for r in successful_tests]
            avg_duration = sum(durations) / len(durations)
            max_duration = max(durations)
            min_duration = min(durations)
        else:
            avg_duration = max_duration = min_duration = 0

        return {
            'total_requests': len(self.results),
            'successful_requests': len(successful_tests),
            'failed_requests': len(failed_tests),
            'success_rate': (len(successful_tests) / len(self.results)) * 100,
            'average_duration': avg_duration,
            'max_duration': max_duration,
            'min_duration': min_duration,
            'failed_details': failed_tests
        }

# Example usage
def main():
    lambda_client = boto3.client('lambda', region_name='us-east-1')

    tester = ServerlessPerformanceTester(
        lambda_client=lambda_client,
        function_name='my-api-test-function'
    )

    # Test payload
    payload = {
        'httpMethod': 'GET',
        'path': '/api/users',
        'headers': {'Authorization': 'Bearer token'},
        'queryStringParameters': {'page': '1', 'limit': '10'}
    }

    # Run 1000 concurrent tests with 100 concurrent users
    tester.run_concurrent_tests(payload, concurrent_users=100, total_requests=1000)

    # Generate report
    report = tester.generate_report()
    print(json.dumps(report, indent=2))

if __name__ == "__main__":
    main()

