import boto3
from datetime import datetime, timedelta
import json

class JenkinsCostOptimizer:
    def __init__(self):
        self.ec2_client = boto3.client('ec2')
        self.cloudwatch = boto3.client('cloudwatch')
        self.ce_client = boto3.client('ce')

    def get_cost_and_usage(self, days=30):
        """Get cost and usage data for Jenkins resources"""
        end_date = datetime.now().date()
        start_date = end_date - timedelta(days=days)

        response = self.ce_client.get_cost_and_usage(
            TimePeriod={
                'Start': start_date.strftime('%Y-%m-%d'),
                'End': end_date.strftime('%Y-%m-%d')
            },
            Granularity='DAILY',
            Metrics=['UnblendedCost'],
            GroupBy=[
                {'Type': 'DIMENSION', 'Key': 'SERVICE'},
                {'Type': 'DIMENSION', 'Key': 'INSTANCE_TYPE'}
            ],
            Filter={
                'Tags': {
                    'Key': 'Environment',
                    'Values': ['jenkins']
                }
            }
        )

        return response

    def analyze_instance_utilization(self, instance_ids):
        """Analyze CPU and memory utilization for instances"""
        utilization_data = {}

        for instance_id in instance_ids:
            # Get CPU utilization
            cpu_response = self.cloudwatch.get_metric_statistics(
                Namespace='AWS/EC2',
                MetricName='CPUUtilization',
                Dimensions=[{'Name': 'InstanceId', 'Value': instance_id}],
                StartTime=datetime.now() - timedelta(days=7),
                EndTime=datetime.now(),
                Period=3600,
                Statistics=['Average']
            )

            # Calculate average utilization
            if cpu_response['Datapoints']:
                avg_cpu = sum([dp['Average'] for dp in cpu_response['Datapoints']]) / len(cpu_response['Datapoints'])
            else:
                avg_cpu = 0

            utilization_data[instance_id] = {
                'average_cpu': avg_cpu,
                'recommendation': self._get_rightsizing_recommendation(avg_cpu)
            }

        return utilization_data

    def _get_rightsizing_recommendation(self, avg_cpu):
        """Get rightsizing recommendation based on utilization"""
        if avg_cpu < 20:
            return 'Downsize to smaller instance type'
        elif avg_cpu > 80:
            return 'Consider upsizing or adding more instances'
        else:
            return 'Instance size appears appropriate'

    def get_spot_instance_opportunities(self):
        """Identify opportunities for spot instance usage"""
        response = self.ec2_client.describe_spot_price_history(
            InstanceTypes=['m5.large', 'm5.xlarge', 'c5.large', 'c5.xlarge'],
            ProductDescriptions=['Linux/UNIX'],
            StartTime=datetime.now() - timedelta(hours=1),
            MaxResults=100
        )

        opportunities = {}
        for price in response['SpotPriceHistory']:
            instance_type = price['InstanceType']
            if instance_type not in opportunities:
                opportunities[instance_type] = []
            opportunities[instance_type].append(float(price['SpotPrice']))

        # Calculate average spot prices
        avg_prices = {}
        for instance_type, prices in opportunities.items():
            avg_prices[instance_type] = sum(prices) / len(prices)

        return avg_prices

    def generate_cost_report(self):
        """Generate comprehensive cost optimization report"""
        # Get cost data
        cost_data = self.get_cost_and_usage()

        # Get instance utilization
        instances = self._get_jenkins_instances()
        utilization = self.analyze_instance_utilization(instances)

        # Get spot opportunities
        spot_opportunities = self.get_spot_instance_opportunities()

        report = {
            'generated_at': datetime.now().isoformat(),
            'cost_analysis': cost_data,
            'utilization_analysis': utilization,
            'spot_opportunities': spot_opportunities,
            'recommendations': self._generate_recommendations(cost_data, utilization, spot_opportunities)
        }

        return report

    def _get_jenkins_instances(self):
        """Get list of Jenkins EC2 instances"""
        response = self.ec2_client.describe_instances(
            Filters=[
                {'Name': 'tag:Environment', 'Values': ['jenkins']},
                {'Name': 'instance-state-name', 'Values': ['running']}
            ]
        )

        instances = []
        for reservation in response['Reservations']:
            for instance in reservation['Instances']:
                instances.append(instance['InstanceId'])

        return instances

    def _generate_recommendations(self, cost_data, utilization, spot_opportunities):
        """Generate cost optimization recommendations"""
        recommendations = []

        # Rightsizing recommendations
        for instance_id, data in utilization.items():
            if data['average_cpu'] < 20:
                recommendations.append({
                    'type': 'rightsizing',
                    'instance': instance_id,
                    'current_utilization': data['average_cpu'],
                    'recommendation': 'Downsize instance type',
                    'estimated_savings': '30-50%'
                })

        # Spot instance recommendations
        for instance_type, avg_price in spot_opportunities.items():
            recommendations.append({
                'type': 'spot_opportunity',
                'instance_type': instance_type,
                'average_spot_price': avg_price,
                'estimated_savings': f"{((0.15 - avg_price) / 0.15 * 100):.1f}%",
                'recommendation': 'Use spot instances for non-critical builds'
            })

        return recommendations

# Example usage
if __name__ == "__main__":
    optimizer = JenkinsCostOptimizer()
    report = optimizer.generate_cost_report()

    print("Jenkins Cost Optimization Report")
    print("=" * 50)

    for rec in report['recommendations']:
        print(f"\n{rec['type'].upper()} - {rec['instance'] if 'instance' in rec else rec['instance_type']}")
        print(f"Recommendation: {rec['recommendation']}")
        print(f"Estimated Savings: {rec['estimated_savings']}")

// ✅ BEST PRACTICE: Modular, parameterized pipeline with clear stages
pipeline {
    agent any

    // Externalized configuration
    parameters {
        choice(
            name: 'DEPLOY_ENVIRONMENT',
            choices: ['dev', 'staging', 'production'],
            description: 'Target deployment environment'
        )
        booleanParam(
            name: 'RUN_INTEGRATION_TESTS',
            defaultValue: true,
            description: 'Execute integration test suite'
        )
        booleanParam(
            name: 'RUN_SECURITY_SCAN',
            defaultValue: true,
            description: 'Execute security vulnerability scan'
        )
    }

    // Environment-specific configuration
    environment {
        // Credentials from Jenkins credential store
        DOCKER_CREDENTIALS = credentials('docker-hub')
        SONARQUBE_TOKEN = credentials('sonarqube-token')

        // Environment variables
        NODE_VERSION = '18'
        MAVEN_OPTS = '-Xmx2g -XX:MaxPermSize=512m'
    }

    options {
        // Pipeline behavior configuration
        timeout(time: 30, unit: 'MINUTES')
        retry(2)
        buildDiscarder(logRotator(numToKeepStr: '10'))
        disableConcurrentBuilds()
    }

    stages {
        // Stage 1: Code Quality
        stage('Code Quality') {
            parallel {
                stage('Static Analysis') {
                    steps {
                        script {
                            sh 'mvn sonar:sonar -Dsonar.token=$SONARQUBE_TOKEN'
                        }
                    }
                }
                stage('Dependency Check') {
                    steps {
                        script {
                            sh 'mvn org.owasp:dependency-check-maven:check'
                        }
                    }
                }
            }
            post {
                always {
                    // Archive results regardless of stage outcome
                    dependencyCheckPublisher pattern: '**/dependency-check-report.xml'
                }
            }
        }

        // Stage 2: Build and Unit Tests
        stage('Build & Unit Tests') {
            steps {
                script {
                    sh 'mvn clean compile test -DskipIntegrationTests=true'
                }
            }
            post {
                always {
                    junit '**/target/surefire-reports/*.xml'
                    publishHTML([
                        target: [
                            reportDir: 'target/site/jacoco',
                            reportFiles: 'index.html',
                            reportName: 'Code Coverage'
                        ]
                    ])
                }
            }
        }

        // Stage 3: Integration Tests (Conditional)
        stage('Integration Tests') {
            when {
                expression { params.RUN_INTEGRATION_TESTS }
            }
            steps {
                script {
                    sh 'mvn verify -DskipUnitTests=true'
                }
            }
        }

        // Stage 4: Security Scan (Conditional)
        stage('Security Scan') {
            when {
                expression { params.RUN_SECURITY_SCAN }
            }
            steps {
                script {
                    sh 'trivy image --exit-code 1 $DOCKER_REGISTRY/$IMAGE_NAME:$BUILD_TAG'
                }
            }
        }

        // Stage 5: Deployment with Approval
        stage('Deploy to Staging') {
            when {
                expression { params.DEPLOY_ENVIRONMENT in ['staging', 'production'] }
            }
            steps {
                script {
                    // Manual approval for staging deployment
                    input message: 'Deploy to staging?', ok: 'Deploy'
                    sh 'kubectl apply -f k8s/staging-deployment.yaml'
                }
            }
        }

        // Stage 6: Production Deployment
        stage('Deploy to Production') {
            when {
                expression { params.DEPLOY_ENVIRONMENT == 'production' }
            }
            steps {
                script {
                    // Multiple approvers for production
                    input(
                        message: 'Deploy to production?',
                        ok: 'Deploy',
                        submitterParameter: 'APPROVED_BY',
                        parameters: [
                            string(
                                name: 'DEPLOYMENT_NOTES',
                                description: 'Deployment notes and rationale'
                            )
                        ]
                    )
                    sh 'kubectl apply -f k8s/production-deployment.yaml'
                }
            }
        }
    }

    post {
        // Comprehensive post-build actions
        always {
            script {
                // Clean up workspace
                cleanWs()

                // Update build description
                currentBuild.description = "${params.DEPLOY_ENVIRONMENT.toUpperCase()} - ${currentBuild.currentResult}"
            }
        }
        success {
            script {
                // Success notifications
                slackSend(
                    channel: '#builds',
                    message: "✅ ${env.JOB_NAME} #${env.BUILD_NUMBER} succeeded"
                )
            }
        }
        failure {
            script {
                // Failure notifications with context
                slackSend(
                    channel: '#build-failures',
                    message: "❌ ${env.JOB_NAME} #${env.BUILD_NUMBER} failed - ${env.BUILD_URL}"
                )
            }
        }
        unstable {
            script {
                // Unstable build handling
                emailext(
                    subject: "${env.JOB_NAME} - Build #${env.BUILD_NUMBER} - UNSTABLE",
                    body: "Build is unstable. Please check test results.",
                    to: 'team@company.com'
                )
            }
        }
    }
}

// ✅ GOOD: Organized, documented shared library functions

/**
 * Build application with Maven
 * @param params Map containing build parameters
 * @param params.javaVersion Java version to use (default: 11)
 * @param params.buildProfile Maven profile to use
 * @param params.skipTests Whether to skip tests
 */
def mavenBuild(Map params = [:]) {
    def javaVersion = params.javaVersion ?: '11'
    def buildProfile = params.buildProfile ?: ''
    def skipTests = params.skipTests ?: false

    withEnv(["JAVA_HOME=${tool "jdk${javaVersion}"}"]) {
        def goals = ['clean', 'compile']

        if (!skipTests) {
            goals += 'test'
        }

        if (buildProfile) {
            goals += "-P${buildProfile}"
        }

        sh "mvn ${goals.join(' ')}"
    }
}

/**
 * Run security scan using OWASP Dependency Check
 * @param scanType Type of scan (application, container, infrastructure)
 * @param failOnCritical Whether to fail build on critical vulnerabilities
 */
def securityScan(String scanType = 'application', Boolean failOnCritical = true) {
    def scanCommands = [
        'application': 'mvn org.owasp:dependency-check-maven:check -DfailBuildOnCVSS=8',
        'container': 'trivy image --exit-code 1 --severity CRITICAL ${DOCKER_IMAGE}',
        'infrastructure': 'terraform scan --security-checks'
    ]

    if (!scanCommands.containsKey(scanType)) {
        error "Unsupported scan type: ${scanType}. Supported types: ${scanCommands.keySet()}"
    }

    try {
        sh scanCommands[scanType]
    } catch (Exception e) {
        if (failOnCritical) {
            error "Security scan failed with critical vulnerabilities: ${e.message}"
        } else {
            echo "WARNING: Security scan completed with vulnerabilities: ${e.message}"
            currentBuild.result = 'UNSTABLE'
        }
    }
}

/**
 * Deploy application to Kubernetes
 * @param environment Target environment (dev, staging, production)
 * @param namespace Kubernetes namespace
 * @param imageTag Docker image tag to deploy
 * @param rolloutWait Whether to wait for rollout completion
 */
def deployToKubernetes(String environment, String namespace, String imageTag, Boolean rolloutWait = true) {
    // Validate environment
    def validEnvironments = ['dev', 'staging', 'production']
    if (!validEnvironments.contains(environment)) {
        error "Invalid environment: ${environment}. Must be one of: ${validEnvironments}"
    }

    // Apply environment-specific configuration
    sh "kubectl apply -f k8s/${environment}/"

    // Update deployment with new image
    sh "kubectl set image deployment/app-server app=registry.company.com/app:${imageTag} -n ${namespace}"

    if (rolloutWait) {
        // Wait for rollout to complete
        timeout(time: 5, unit: 'MINUTES') {
            sh "kubectl rollout status deployment/app-server -n ${namespace}"
        }
    }

    // Verify deployment
    sh "kubectl get pods -n ${namespace} -l app=app-server"
}

/**
 * Send deployment notification
 * @param environment Deployment environment
 * @param status Deployment status (success, failure, rollback)
 * @param additionalInfo Additional context for notification
 */
def sendDeploymentNotification(String environment, String status, Map additionalInfo = [:]) {
    def notificationTemplates = [
        success: "✅ Successfully deployed to ${environment}",
        failure: "❌ Deployment to ${environment} failed",
        rollback: "🔄 Rolled back deployment to ${environment}"
    ]

    def message = notificationTemplates[status]
    if (!message) {
        error "Invalid deployment status: ${status}"
    }

    // Add additional context if provided
    if (additionalInfo) {
        message += "\nAdditional Info: ${additionalInfo.inspect()}"
    }

    // Send to multiple channels
    slackSend(
        channel: '#deployments',
        message: message,
        color: status == 'success' ? 'good' : 'danger'
    )

    // Also send email for critical environments
    if (environment == 'production') {
        emailext(
            to: 'engineering@company.com',
            subject: "Deployment ${status.capitalize()} - ${environment}",
            body: message
        )
    }
}

// ✅ GOOD: Robust error handling with recovery patterns

/**
 * Execute step with retry logic for transient failures
 * @param step Closure containing the step to execute
 * @param maxAttempts Maximum number of retry attempts (default: 3)
 * @param retryDelay Delay between retries in seconds (default: 5)
 * @param retryConditions List of exception patterns that should trigger retry
 */
def executeWithRetry(Closure step, int maxAttempts = 3, int retryDelay = 5, List retryConditions = []) {
    def attempts = 0
    def lastException = null

    while (attempts < maxAttempts) {
        attempts++

        try {
            step()
            echo "Step completed successfully on attempt ${attempts}"
            return // Success, exit the method

        } catch (Exception e) {
            lastException = e

            // Check if this error should be retried
            def shouldRetry = shouldRetryOnError(e, retryConditions)

            if (shouldRetry && attempts < maxAttempts) {
                echo "Attempt ${attempts} failed with retryable error: ${e.message}"
                echo "Retrying in ${retryDelay} seconds..."
                sleep(retryDelay)

                // Exponential backoff for subsequent retries
                retryDelay = retryDelay * 2

            } else if (shouldRetry) {
                error "Step failed after ${maxAttempts} attempts. Last error: ${e.message}"
            } else {
                // Non-retryable error, re-throw immediately
                error "Step failed with non-retryable error: ${e.message}"
            }
        }
    }
}

/**
 * Determine if an error should trigger a retry
 * @param exception The exception that occurred
 * @param retryConditions List of patterns that indicate retryable errors
 */
def shouldRetryOnError(Exception exception, List retryConditions = []) {
    def defaultRetryConditions = [
        ~/.*Connection.*timeout.*/,
        ~/.*Network.*unreachable.*/,
        ~/.*Temporary.*failure.*/,
        ~/.*Rate.*limit.*exceeded.*/,
        ~/.*5\d\d.*/, // HTTP 5xx errors
        ~/.*socket.*exception.*/
    ]

    def allConditions = retryConditions + defaultRetryConditions
    def errorMessage = exception.message ?: ''

    return allConditions.any { pattern ->
        errorMessage ==~ pattern
    }
}

/**
 * Execute step with timeout and proper cleanup
 * @param step Closure containing the step to execute
 * @param timeoutMinutes Timeout in minutes
 * @param cleanup Closure to execute on timeout or failure
 */
def executeWithTimeout(Closure step, int timeoutMinutes = 10, Closure cleanup = null) {
    def timeoutSeconds = timeoutMinutes * 60

    try {
        timeout(time: timeoutMinutes, unit: 'MINUTES') {
            step()
        }
    } catch (org.jenkinsci.plugins.workflow.steps.FlowInterruptedException e) {
        echo "Step timed out after ${timeoutMinutes} minutes"

        // Execute cleanup if provided
        if (cleanup) {
            echo "Executing cleanup procedures..."
            try {
                cleanup()
            } catch (Exception cleanupException) {
                echo "Cleanup also failed: ${cleanupException.message}"
            }
        }

        error "Execution timed out after ${timeoutMinutes} minutes"
    }
}

/**
 * Handle deployment failures with automatic rollback
 * @param deployment Closure containing deployment logic
 * @param rollback Closure containing rollback logic
 * @param healthCheck Closure to verify deployment health
 */
def deployWithRollback(Closure deployment, Closure rollback, Closure healthCheck = null) {
    def originalVersion = getCurrentDeploymentVersion()

    try {
        // Execute deployment
        deployment()

        // Verify deployment health if health check provided
        if (healthCheck) {
            echo "Verifying deployment health..."
            def healthCheckPassed = false

            // Retry health check with backoff
            executeWithRetry({
                healthCheckPassed = healthCheck()
                if (!healthCheckPassed) {
                    throw new Exception("Health check failed")
                }
            }, 5, 10)

            if (!healthCheckPassed) {
                throw new Exception("Deployment health check failed after multiple attempts")
            }
        }

        echo "Deployment completed successfully"

    } catch (Exception e) {
        echo "Deployment failed: ${e.message}. Initiating rollback..."

        try {
            // Execute rollback
            rollback()
            echo "Rollback completed successfully"

            // Verify rollback
            def rolledBackVersion = getCurrentDeploymentVersion()
            if (rolledBackVersion == originalVersion) {
                echo "Successfully rolled back to version: ${originalVersion}"
            } else {
                error "Rollback may not have completed correctly. Expected: ${originalVersion}, Actual: ${rolledBackVersion}"
            }

        } catch (Exception rollbackException) {
            error "Both deployment and rollback failed. Manual intervention required. Deployment error: ${e.message}, Rollback error: ${rollbackException.message}"
        }

        // Re-throw the original deployment error
        error "Deployment failed and was rolled back: ${e.message}"
    }
}

/**
 * Comprehensive pipeline stage with error handling
 */
def safePipelineStage(String stageName, Closure stageLogic, Map options = [:]) {
    def defaults = [
        timeout: 30,
        retryAttempts: 2,
        continueOnError: false,
        cleanup: null
    ]

    def config = defaults + options

    stage(stageName) {
        try {
            executeWithTimeout({
                executeWithRetry(stageLogic, config.retryAttempts)
            }, config.timeout)

        } catch (Exception e) {
            echo "Stage '${stageName}' failed: ${e.message}"

            // Execute cleanup if provided
            if (config.cleanup) {
                echo "Executing stage cleanup..."
                try {
                    config.cleanup()
                } catch (Exception cleanupException) {
                    echo "Stage cleanup failed: ${cleanupException.message}"
                }
            }

            // Handle error based on configuration
            if (config.continueOnError) {
                echo "Continuing pipeline despite stage failure (continueOnError=true)"
                currentBuild.result = 'UNSTABLE'
            } else {
                error "Stage '${stageName}' failed and cannot continue: ${e.message}"
            }
        }
    }
}

