                    sh '''
                        mvn clean compile \
                            -T ${MAVEN_THREADS} \
                            -Dmaven.test.failure.ignore=true \
                            -Dmaven.test.redirectTestOutputToFile=true

                        # ✅ OPTIMIZED: Run tests in parallel
                        mvn test \
                            -T ${MAVEN_THREADS} \
                            -Dparallel=classes \
                            -DthreadCount=4 \
                            -DuseUnlimitedThreads=false
                    '''
                }
