    cy.get('[data-testid="username-input"]')
      .invoke('prop', 'validationMessage')
      .should('contain', 'Please fill out this field');

    cy.get('[data-testid="password-input"]')
      .parent()
      .should('have.class', 'error');
  });

  it('should handle network errors gracefully', () => {
    // Intercept login API call and force failure
    cy.intercept('POST', '/api/login', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('loginApi');

    cy.get('[data-testid="username-input"]').type('testuser');
    cy.get('[data-testid="password-input"]').type('password');
    cy.get('[data-testid="login-button"]').click();

    // Wait for API call and verify error handling
    cy.wait('@loginApi');
    cy.get('[data-testid="api-error"]')
      .should('be.visible')
      .and('contain', 'Service temporarily unavailable');
  });

  it('should persist login state after page refresh', () => {
