    await expect(page).toHaveURL(/.*inventory.html/);
    await expect(page.locator('.title')).toContainText('Products');

    // Verify inventory items are visible
    await expect(page.locator('.inventory_item')).toHaveCountGreaterThan(0);
  });

  test('failed login with locked out user', async ({ page }) => {
    // Fill login form with locked out user
    await page.fill('[data-test="username"]', testUsers.locked.username);
    await page.fill('[data-test="password"]', testUsers.locked.password);
    await page.click('[data-test="login-button"]');

