    await expect(page.locator('[data-test="error"]'))
      .toBeVisible();
    await expect(page.locator('[data-test="error"]'))
      .toContainText('Sorry, this user has been locked out');

    // Verify still on login page
    await expect(page).toHaveURL('https://www.saucedemo.com/');
  });

  test('login with problem user should show issues', async ({ page, browserName }) => {
    // Skip this test in Firefox due to known compatibility issues
    test.skip(browserName === 'firefox', 'Problem user test unstable in Firefox');

    await page.fill('[data-test="username"]', testUsers.problem.username);
    await page.fill('[data-test="password"]', testUsers.problem.password);
    await page.click('[data-test="login-button"]');

    // Problem user has broken images
    const images = page.locator('img');
    const count = await images.count();

    for (let i = 0; i < count; i++) {
      const image = images.nth(i);
      const isVisible = await image.isVisible();
      if (isVisible) {
        const naturalWidth = await image.evaluate(el => el.naturalWidth);
        // Problem user has broken images (naturalWidth === 0)
        if (naturalWidth === 0) {
          console.log(`Broken image found: ${await image.getAttribute('src')}`);
        }
      }
    }
