    await page.fill('[data-test="password"]', testUsers.standard.password);
    await page.click('[data-test="login-button"]');

    // Wait for navigation to complete
    await page.waitForURL(/.*inventory.html/);

    const endTime = Date.now();
    const duration = endTime - startTime;

    // Assert performance requirement
    expect(duration).toBeLessThan(2000);

    console.log(`Login completed in ${duration}ms`);
  });

  test('visual testing: login page should match screenshot', async ({ page }) => {
    // Take screenshot and compare with baseline
    await expect(page).toHaveScreenshot('login-page.png', {
      maxDiffPixels: 100,
      animations: 'disabled'
    });
  });

  test('mobile view: login should work on mobile devices', async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });

    // Verify responsive design
    await expect(page.locator('.login_wrapper')).toBeVisible();

