pipeline {
    agent {
        kubernetes {
            label 'maven-jdk11'
            yaml '''
                apiVersion: v1
                kind: Pod
                metadata:
                  labels:
                    app: java-build
                spec:
                  containers:
                  - name: maven
                    image: maven:3.8.1-openjdk-11
                    command: ['cat']
                    tty: true
                    resources:
                      requests:
                        memory: "2Gi"
                        cpu: "1000m"
                      limits:
                        memory: "4Gi"
                        cpu: "2000m"
                    volumeMounts:
                    - name: maven-cache
                      mountPath: /root/.m2
                  - name: docker
                    image: docker:20.10
                    command: ['cat']
                    tty: true
                    volumeMounts:
                    - name: docker-sock
                      mountPath: /var/run/docker.sock
                  volumes:
                  - name: maven-cache
                    persistentVolumeClaim:
                      claimName: maven-cache-pvc
                  - name: docker-sock
                    hostPath:
                      path: /var/run/docker.sock
            '''
        }
    }

    options {
        timeout(time: 30, unit: 'MINUTES')
        buildDiscarder(logRotator(numToKeepStr: '10'))
        disableConcurrentBuilds()
        timestamps()
    }

    environment {
        DOCKER_REGISTRY = credentials('docker-registry')
        SONARQUBE_TOKEN = credentials('sonarqube-token')
        SLACK_WEBHOOK = credentials('slack-webhook')
        APP_VERSION = "${env.BUILD_ID}-${env.GIT_COMMIT.take(8)}"
    }

    stages {
        stage('Checkout & Setup') {
            steps {
                checkout scm
                sh 'git branch -a'
            }
        }

        stage('Dependency Check') {
            steps {
                sh 'mvn dependency:tree'
                sh 'mvn dependency:analyze'
            }
        }

        stage('Code Quality') {
            parallel {
                stage('Static Analysis') {
                    steps {
                        withSonarQubeEnv('sonarqube-server') {
                            sh 'mvn sonar:sonar -Dsonar.projectVersion=${APP_VERSION}'
                        }
                    }
                }
                stage('Security Scan') {
                    steps {
                        sh 'mvn org.owasp:dependency-check-maven:check'
                    }
                }
            }
        }

        stage('Build & Test') {
            parallel {
                stage('Unit Tests') {
                    steps {
                        sh 'mvn clean test -DskipITs=true'
                    }
                    post {
                        always {
                            junit 'target/surefire-reports/*.xml'
                        }
                    }
                }
                stage('Integration Tests') {
                    steps {
                        sh 'mvn verify -Dsurefire.skip=true -DskipITs=false'
                    }
                    post {
                        always {
                            junit 'target/failsafe-reports/*.xml'
                        }
                    }
                }
            }
        }

        stage('Quality Gate') {
            steps {
                timeout(time: 5, unit: 'MINUTES') {
                    waitForQualityGate abortPipeline: true
                }
            }
        }

        stage('Build Docker Image') {
            when {
                expression { env.BRANCH_NAME == 'main' || env.BRANCH_NAME == 'develop' }
            }
            steps {
                container('docker') {
                    sh '''
                        docker build -t ${DOCKER_REGISTRY}/myapp:${APP_VERSION} .
                        docker push ${DOCKER_REGISTRY}/myapp:${APP_VERSION}
                    '''
                }
            }
        }

        stage('Deploy to Staging') {
            when {
                expression { env.BRANCH_NAME == 'main' }
            }
            steps {
                sh '''
                    kubectl set image deployment/myapp myapp=${DOCKER_REGISTRY}/myapp:${APP_VERSION}
                    kubectl rollout status deployment/myapp
                '''
            }
        }
    }

    post {
        always {
            script {
                def currentBuild = currentBuild
                def buildStatus = currentBuild.result ?: 'SUCCESS'

                // Send Slack notification
                slackSend(
                    channel: '#builds',
                    message: "Build ${buildStatus}: ${env.JOB_NAME} #${env.BUILD_NUMBER}\nBranch: ${env.BRANCH_NAME}\nCommit: ${env.GIT_COMMIT.take(8)}\nBuild URL: ${env.BUILD_URL}"
                )

                // Cleanup workspace
                cleanWs()
            }
        }
        success {
            emailext (
                subject: "SUCCESS: Job '${env.JOB_NAME} [${env.BUILD_NUMBER}]'",
                body: "${currentBuild.currentResult}: Job '${env.JOB_NAME} [${env.BUILD_NUMBER}]':\nCheck console output at ${env.BUILD_URL}",
                to: 'dev-team@company.com'
            )
        }
        failure {
            emailext (
                subject: "FAILED: Job '${env.JOB_NAME} [${env.BUILD_NUMBER}]'",
                body: "${currentBuild.currentResult}: Job '${env.JOB_NAME} [${env.BUILD_NUMBER}]':\nCheck console output at ${env.BUILD_URL}",
                to: 'dev-team@company.com'
            )
        }
    }
}

